INSERT INTO sat_questions (question_id, external_id, vault_id, disclosed_item_id, source, program, test_type, test_type_desc, domain, primary_class_cd, skill_cd, skill_desc, difficulty, score_band_range_cd, question_type, stimulus_html, stem_html, answer_options, correct_answer, answer_keys, rationale_html, correct_answer_extracted_from_rationale, image_count, parent_template_name, parent_template_id, template_cluster_id, template_cluster_name, origin, position, answer_style, section, raw_payload, created_date, updated_date) VALUES
    ($SATQ$c071eca2$SATQ$, $SATQ$74f4478d-92d2-4a5a-a41b-76bbd45f8a42$SATQ$::uuid, $SATQ$e519decb-dc82-46fd-8996-b1cfa092b494$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>Iraqi artist Nazik Al-Malaika, celebrated as the first Arabic poet to write in free verse, didn&rsquo;t reject traditional forms entirely; her poem &ldquo;Elegy for a Woman of No Importance&rdquo; consists of two ten-line stanzas and a standard number of syllables. Even in this superficially traditional work, <span aria-hidden="true">______</span><span class="sr-only">blank</span> Al-Malaika was breaking new ground by memorializing an anonymous woman rather than a famous man.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"078aff14-389e-4592-8b0f-0aaf93776d75","content":"<p>therefore,</p>"},{"id":"235e77df-83a0-4e31-87df-24e018e26b6d","content":"<p>in fact,</p>"},{"id":"fdb36329-abf4-496f-9b54-18cf03e69ad0","content":"<p>moreover,</p>"},{"id":"10ac1eb6-8081-4ed0-9e83-2759e3c7a925","content":"<p>though,</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["10ac1eb6-8081-4ed0-9e83-2759e3c7a925"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The first sentence tells us that Al-Malaika sometimes used "traditional forms". The second tells us that even when she used traditional forms, Al-Malaika was "breaking new ground". To connect these ideas, we need a contrast word like "but." "Though" is a contrast word similar to "but."</p><p>Choice A is incorrect. This isn&rsquo;t a logical transition. The first sentence tells us that Al-Malaika sometimes used "traditional forms". The second tells us that even when she used traditional forms, Al-Malaika was "breaking new ground". To connect these ideas, we need a contrast word like "but." "Therefore" doesn&rsquo;t show contrast; it shows cause and effect. Choice B is incorrect. This isn&rsquo;t a logical transition. The first sentence tells us that Al-Malaika sometimes used "traditional forms". The second tells us that even when she used traditional forms, Al-Malaika was "breaking new ground". To connect these ideas, we need a contrast word like "but." "In fact" is a phrase that usually emphasizes the truth of the previous statement. Choice C is incorrect. This isn&rsquo;t a logical transition. The first sentence tells us that Al-Malaika sometimes used "traditional forms". The second tells us that even when she used traditional forms, Al-Malaika was "breaking new ground". To connect these ideas, we need a contrast word like "but." "Moreover" doesn&rsquo;t show contrast&mdash;it introduces additional information that continues or supports the previous idea.</p>$SATQ$, false, 0, $SATQ$OSP-208-TRA$SATQ$, $SATQ$$SATQ$, $SATQ$39a59fdc-ee28-45c4-b211-9999c97d142c$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"c071eca2","external_id":"74f4478d-92d2-4a5a-a41b-76bbd45f8a42","vaultid":"e519decb-dc82-46fd-8996-b1cfa092b494","uId":"795fc7c1-e0c8-49eb-bb4c-e24c26674165","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>Iraqi artist Nazik Al-Malaika, celebrated as the first Arabic poet to write in free verse, didn&rsquo;t reject traditional forms entirely; her poem &ldquo;Elegy for a Woman of No Importance&rdquo; consists of two ten-line stanzas and a standard number of syllables. Even in this superficially traditional work, <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> Al-Malaika was breaking new ground by memorializing an anonymous woman rather than a famous man.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"078aff14-389e-4592-8b0f-0aaf93776d75","content":"<p>therefore,</p>"},{"id":"235e77df-83a0-4e31-87df-24e018e26b6d","content":"<p>in fact,</p>"},{"id":"fdb36329-abf4-496f-9b54-18cf03e69ad0","content":"<p>moreover,</p>"},{"id":"10ac1eb6-8081-4ed0-9e83-2759e3c7a925","content":"<p>though,</p>"}],"keys":["10ac1eb6-8081-4ed0-9e83-2759e3c7a925"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The first sentence tells us that Al-Malaika sometimes used \"traditional forms\". The second tells us that even when she used traditional forms, Al-Malaika was \"breaking new ground\". To connect these ideas, we need a contrast word like \"but.\" \"Though\" is a contrast word similar to \"but.\"</p><p>Choice A is incorrect. This isn&rsquo;t a logical transition. The first sentence tells us that Al-Malaika sometimes used \"traditional forms\". The second tells us that even when she used traditional forms, Al-Malaika was \"breaking new ground\". To connect these ideas, we need a contrast word like \"but.\" \"Therefore\" doesn&rsquo;t show contrast; it shows cause and effect. Choice B is incorrect. This isn&rsquo;t a logical transition. The first sentence tells us that Al-Malaika sometimes used \"traditional forms\". The second tells us that even when she used traditional forms, Al-Malaika was \"breaking new ground\". To connect these ideas, we need a contrast word like \"but.\" \"In fact\" is a phrase that usually emphasizes the truth of the previous statement. Choice C is incorrect. This isn&rsquo;t a logical transition. The first sentence tells us that Al-Malaika sometimes used \"traditional forms\". The second tells us that even when she used traditional forms, Al-Malaika was \"breaking new ground\". To connect these ideas, we need a contrast word like \"but.\" \"Moreover\" doesn&rsquo;t show contrast&mdash;it introduces additional information that continues or supports the previous idea.</p>","parenttemplatename":"OSP-208-TRA","parenttemplateid":"","templateclusterid":"39a59fdc-ee28-45c4-b211-9999c97d142c","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959326,"updateDate":1691007959326}$SATQ$::jsonb, 1691007959326, 1691007959326),
    ($SATQ$c34d6bff$SATQ$, $SATQ$895349d7-a567-400f-9de6-a4f1de149e22$SATQ$::uuid, $SATQ$49960634-2cbc-48dc-b3dd-c33976b4376f$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>African American women played prominent roles in the Civil Rights Movement, including at the famous 1963 March on Washington.</li>
<li>Civil rights activist Anna Hedgeman, one of the march&rsquo;s organizers, was a political adviser who had worked for President Truman.</li>
<li>Civil rights activist Daisy Bates was a well-known journalist and advocate for school desegregation.</li>
<li>Hedgeman worked behind the scenes to make sure a woman was included in the lineup of speakers at the march.</li>
<li>Bates was the sole woman to speak, delivering a brief but memorable address to the cheering crowd.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to compare the two women&rsquo;s contributions to the March on Washington. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"40f8a5be-990e-4ba5-9bd5-75be0d5fe200","content":"<p>Hedgeman and Bates contributed to the march in different ways; Bates, for example, delivered a brief but memorable address.</p>"},{"id":"e6912f92-10a6-4567-b311-409c94245ece","content":"<p>Hedgeman worked in politics and helped organize the march, while Bates was a journalist and school desegregation advocate.</p>"},{"id":"cfa25c17-d93d-4f39-92c4-a022d76fcd0e","content":"<p>Although Hedgeman worked behind the scenes to make sure a woman speaker was included, Bates was the sole woman to speak at the march.</p>"},{"id":"1de10577-413a-493a-979a-7016a9af3faa","content":"<p>Many African American women, including Bates and Hedgeman, fought for civil rights, but only one spoke at the march.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["cfa25c17-d93d-4f39-92c4-a022d76fcd0e"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The sentence compares the two women&rsquo;s contributions to the march: Hedgeman worked behind the scenes to make sure a woman speaker was included, whereas Bates actually spoke at the event.&nbsp;</p><p>Choice A is incorrect. While it acknowledges that the two women both contributed to the march, it doesn&rsquo;t indicate what Hedgeman did, so no comparison is made. Choice B is incorrect. While the sentence provides information about the two women, it doesn&rsquo;t mention anything about Bates&rsquo;s contribution to the march.&nbsp;Choice D is incorrect. While the sentence indicates that the two women both fought for civil rights, it doesn&rsquo;t compare their individual contributions to the march. </p>$SATQ$, false, 0, $SATQ$OSP-757-SYN$SATQ$, $SATQ$$SATQ$, $SATQ$ad031157-df52-40a0-b807-59974b9bce80$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"c34d6bff","external_id":"895349d7-a567-400f-9de6-a4f1de149e22","vaultid":"49960634-2cbc-48dc-b3dd-c33976b4376f","uId":"c8ee33f9-b76e-4763-881a-22751e0cb6b8","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>African American women played prominent roles in the Civil Rights Movement, including at the famous 1963 March on Washington.</li>\n<li>Civil rights activist Anna Hedgeman, one of the march&rsquo;s organizers, was a political adviser who had worked for President Truman.</li>\n<li>Civil rights activist Daisy Bates was a well-known journalist and advocate for school desegregation.</li>\n<li>Hedgeman worked behind the scenes to make sure a woman was included in the lineup of speakers at the march.</li>\n<li>Bates was the sole woman to speak, delivering a brief but memorable address to the cheering crowd.</li>\n</ul>","stem":"<p>The student wants to compare the two women&rsquo;s contributions to the March on Washington. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"40f8a5be-990e-4ba5-9bd5-75be0d5fe200","content":"<p>Hedgeman and Bates contributed to the march in different ways; Bates, for example, delivered a brief but memorable address.</p>"},{"id":"e6912f92-10a6-4567-b311-409c94245ece","content":"<p>Hedgeman worked in politics and helped organize the march, while Bates was a journalist and school desegregation advocate.</p>"},{"id":"cfa25c17-d93d-4f39-92c4-a022d76fcd0e","content":"<p>Although Hedgeman worked behind the scenes to make sure a woman speaker was included, Bates was the sole woman to speak at the march.</p>"},{"id":"1de10577-413a-493a-979a-7016a9af3faa","content":"<p>Many African American women, including Bates and Hedgeman, fought for civil rights, but only one spoke at the march.</p>"}],"keys":["cfa25c17-d93d-4f39-92c4-a022d76fcd0e"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The sentence compares the two women&rsquo;s contributions to the march: Hedgeman worked behind the scenes to make sure a woman speaker was included, whereas Bates actually spoke at the event.&nbsp;</p><p>Choice A is incorrect. While it acknowledges that the two women both contributed to the march, it doesn&rsquo;t indicate what Hedgeman did, so no comparison is made. Choice B is incorrect. While the sentence provides information about the two women, it doesn&rsquo;t mention anything about Bates&rsquo;s contribution to the march.&nbsp;Choice D is incorrect. While the sentence indicates that the two women both fought for civil rights, it doesn&rsquo;t compare their individual contributions to the march. </p>","parenttemplatename":"OSP-757-SYN","parenttemplateid":"","templateclusterid":"ad031157-df52-40a0-b807-59974b9bce80","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959351,"updateDate":1691007959351}$SATQ$::jsonb, 1691007959351, 1691007959351),
    ($SATQ$c40a1964$SATQ$, $SATQ$020f2cdc-bab1-476b-849b-762e11ace6c1$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>Leigh Torres is a marine ecologist.</li>
<li>She conducted a study of blue whales in New Zealand&rsquo;s South Taranaki Bight region.</li>
<li>She wanted to know how ocean temperature affects where the whales forage for krill in that region.</li>
<li>She found that during a marine heat wave, the whales foraged farther offshore than they had during cooler periods.</li>
<li>The offshore waters, which were colder than areas closer to shore, had a higher relative abundance of krill.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to emphasize the aim of the research study. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"dfc933fe-bf20-44a7-a5ab-e94109171a2a","content":"<p>Analyzing ocean temperature data, Torres found that during a marine heat wave, blue whales foraged farther offshore than they had during cooler periods.</p>"},{"id":"83fdd668-ed3b-4b3c-9303-c70b5e76e9c7","content":"<p>In her study, Torres sought to determine how ocean temperature affects where blue whales forage for krill in the South Taranaki Bight region.</p>"},{"id":"3ec8940e-ddda-4ab6-86b7-71ffe6a975ac","content":"<p>Torres&rsquo;s study revealed that blue whales were attracted to offshore waters with a relatively high abundance of krill.</p>"},{"id":"d44a4a5d-b6d5-4a71-9c5a-4e2c523b3bc3","content":"<p>Torres, a marine ecologist, studied blue whales in the South Taranaki Bight region, where the whales forage.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["83fdd668-ed3b-4b3c-9303-c70b5e76e9c7"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The sentence emphasizes the aim, or goal, of the research study, noting that Torres sought to determine how ocean temperature affects where blue whales forage for krill.</p><p>Choice A is incorrect. The sentence emphasizes the results of the study, noting what Torres found at the end; it doesn&rsquo;t emphasize the aim, or goal, of the study, which is what Torres sought at the beginning. Choice C is incorrect. The sentence makes a claim about the study&rsquo;s results; it doesn&rsquo;t emphasize the aim, or goal, of the study. Choice D is incorrect. The sentence indicates the location of Torres&rsquo;s study; it doesn&rsquo;t emphasize the aim, or goal, of the study.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"c40a1964","external_id":"020f2cdc-bab1-476b-849b-762e11ace6c1","vaultid":null,"uId":"d6870852-b237-4f45-953e-6c3cc5842e30","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>Leigh Torres is a marine ecologist.</li>\n<li>She conducted a study of blue whales in New Zealand&rsquo;s South Taranaki Bight region.</li>\n<li>She wanted to know how ocean temperature affects where the whales forage for krill in that region.</li>\n<li>She found that during a marine heat wave, the whales foraged farther offshore than they had during cooler periods.</li>\n<li>The offshore waters, which were colder than areas closer to shore, had a higher relative abundance of krill.</li>\n</ul>","stem":"<p>The student wants to emphasize the aim of the research study. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"dfc933fe-bf20-44a7-a5ab-e94109171a2a","content":"<p>Analyzing ocean temperature data, Torres found that during a marine heat wave, blue whales foraged farther offshore than they had during cooler periods.</p>"},{"id":"83fdd668-ed3b-4b3c-9303-c70b5e76e9c7","content":"<p>In her study, Torres sought to determine how ocean temperature affects where blue whales forage for krill in the South Taranaki Bight region.</p>"},{"id":"3ec8940e-ddda-4ab6-86b7-71ffe6a975ac","content":"<p>Torres&rsquo;s study revealed that blue whales were attracted to offshore waters with a relatively high abundance of krill.</p>"},{"id":"d44a4a5d-b6d5-4a71-9c5a-4e2c523b3bc3","content":"<p>Torres, a marine ecologist, studied blue whales in the South Taranaki Bight region, where the whales forage.</p>"}],"keys":["83fdd668-ed3b-4b3c-9303-c70b5e76e9c7"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The sentence emphasizes the aim, or goal, of the research study, noting that Torres sought to determine how ocean temperature affects where blue whales forage for krill.</p><p>Choice A is incorrect. The sentence emphasizes the results of the study, noting what Torres found at the end; it doesn&rsquo;t emphasize the aim, or goal, of the study, which is what Torres sought at the beginning. Choice C is incorrect. The sentence makes a claim about the study&rsquo;s results; it doesn&rsquo;t emphasize the aim, or goal, of the study. Choice D is incorrect. The sentence indicates the location of Torres&rsquo;s study; it doesn&rsquo;t emphasize the aim, or goal, of the study.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323047,"updateDate":1730147323047}$SATQ$::jsonb, 1730147323047, 1730147323047),
    ($SATQ$c4f7f726$SATQ$, $SATQ$853cecf5-60d9-4e4f-b550-7a361e2427e8$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>Many butterfly species have bold, brightly colored wings. <span aria-hidden="true">______</span><span class="sr-only">blank</span> some butterfly species have wings that are almost completely colorless and transparent. Glasswing butterflies, for example, have see-through wings that make them nearly invisible.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"2c6ee337-e469-4eb3-a07e-91c0fe1fd6c8","content":"<p>Similarly,</p>"},{"id":"4f524f90-0985-43d6-85a6-29d93603dbfd","content":"<p>Previously,</p>"},{"id":"44783565-a5d8-43b2-98e4-1664627a3780","content":"<p>In other words,</p>"},{"id":"e2c373cb-6247-44b4-b5b1-600729923f2b","content":"<p>However,</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["e2c373cb-6247-44b4-b5b1-600729923f2b"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. "However" logically signals that the information in this sentence about butterfly species&mdash;that some have colorless, transparent wings&mdash;contrasts with the previous information about butterfly species with bold, colorful wings.</p><p>Choice A is incorrect because "similarly" illogically signals that the information in this sentence is similar to the previous information about butterfly species. Instead, it contrasts with the previous information. Choice B is incorrect because "previously" illogically signals that this sentence describes an event that occurred before another event. Instead, the sentence provides information about butterfly species that contrasts with the information in the first sentence. Choice C is incorrect because "in other words" illogically signals that the information in this sentence is a paraphrase or restatement of the previous information about butterfly species. Instead, it contrasts with the previous information.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"c4f7f726","external_id":"853cecf5-60d9-4e4f-b550-7a361e2427e8","vaultid":null,"uId":"b88ce777-10fc-47dc-900d-be626993e955","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>Many butterfly species have bold, brightly colored wings. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> some butterfly species have wings that are almost completely colorless and transparent. Glasswing butterflies, for example, have see-through wings that make them nearly invisible.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"2c6ee337-e469-4eb3-a07e-91c0fe1fd6c8","content":"<p>Similarly,</p>"},{"id":"4f524f90-0985-43d6-85a6-29d93603dbfd","content":"<p>Previously,</p>"},{"id":"44783565-a5d8-43b2-98e4-1664627a3780","content":"<p>In other words,</p>"},{"id":"e2c373cb-6247-44b4-b5b1-600729923f2b","content":"<p>However,</p>"}],"keys":["e2c373cb-6247-44b4-b5b1-600729923f2b"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. \"However\" logically signals that the information in this sentence about butterfly species&mdash;that some have colorless, transparent wings&mdash;contrasts with the previous information about butterfly species with bold, colorful wings.</p><p>Choice A is incorrect because \"similarly\" illogically signals that the information in this sentence is similar to the previous information about butterfly species. Instead, it contrasts with the previous information. Choice B is incorrect because \"previously\" illogically signals that this sentence describes an event that occurred before another event. Instead, the sentence provides information about butterfly species that contrasts with the information in the first sentence. Choice C is incorrect because \"in other words\" illogically signals that the information in this sentence is a paraphrase or restatement of the previous information about butterfly species. Instead, it contrasts with the previous information.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323044,"updateDate":1730147323044}$SATQ$::jsonb, 1730147323044, 1730147323044),
    ($SATQ$c6645cab$SATQ$, $SATQ$482139d3-cce1-49f7-b2a8-5cf84ccb6a29$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li><span data-ssml-sub-alias="Dr">Dr.</span> Sunil Bajpai studies dinosaurs at the Indian Institute of Technology.</li>
<li>Bajpai&rsquo;s research team recently found a 167-million-year-old dicraeosaurid fossil.</li>
<li>It is the oldest fossil from the dicraeosaurid dinosaur group ever recovered.</li>
<li>It was found in the Thar Desert in western India.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to indicate where the dicraeosaurid fossil was found. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"5212254d-2f96-4d48-a0ef-a3eb7d7518fe","content":"<p>The dicraeosaurid fossil was found in western India&rsquo;s Thar Desert.</p>"},{"id":"8f7c313e-9f29-42a7-9ba1-600c689e0cdf","content":"<p>Bajpai&rsquo;s team recently found the oldest dicraeosaurid fossil ever recovered.</p>"},{"id":"49af24e1-8464-4778-b061-9b8083f047e9","content":"<p><span data-ssml-sub-alias=\"Dr\">Dr.</span> Sunil Bajpai, of the Indian Institute of Technology, is part of a research team.</p>"},{"id":"848b8dc6-758b-4bc7-93dd-c883de175ab8","content":"<p>The fossil, which is from the dicraeosaurid dinosaur group, is 167 million years old.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["5212254d-2f96-4d48-a0ef-a3eb7d7518fe"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The sentence indicates where the dicraeosaurid fossil was found: western India&rsquo;s Thar Desert.</p><p>Choice B is incorrect. The sentence states that Bajpai&rsquo;s team discovered the dicraeosaurid fossil; it doesn&rsquo;t specify where they found it. Choice C is incorrect. The sentence provides information about Dr. Sunil Bajpai; it doesn&rsquo;t indicate where the fossil was found. Choice D is incorrect. While the sentence provides information about the fossil, it doesn&rsquo;t indicate where the fossil was found.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"c6645cab","external_id":"482139d3-cce1-49f7-b2a8-5cf84ccb6a29","vaultid":null,"uId":"325d5dc5-286c-4746-95fb-c374aac9facd","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li><span data-ssml-sub-alias=\"Dr\">Dr.</span> Sunil Bajpai studies dinosaurs at the Indian Institute of Technology.</li>\n<li>Bajpai&rsquo;s research team recently found a 167-million-year-old dicraeosaurid fossil.</li>\n<li>It is the oldest fossil from the dicraeosaurid dinosaur group ever recovered.</li>\n<li>It was found in the Thar Desert in western India.</li>\n</ul>","stem":"<p>The student wants to indicate where the dicraeosaurid fossil was found. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"5212254d-2f96-4d48-a0ef-a3eb7d7518fe","content":"<p>The dicraeosaurid fossil was found in western India&rsquo;s Thar Desert.</p>"},{"id":"8f7c313e-9f29-42a7-9ba1-600c689e0cdf","content":"<p>Bajpai&rsquo;s team recently found the oldest dicraeosaurid fossil ever recovered.</p>"},{"id":"49af24e1-8464-4778-b061-9b8083f047e9","content":"<p><span data-ssml-sub-alias=\"Dr\">Dr.</span> Sunil Bajpai, of the Indian Institute of Technology, is part of a research team.</p>"},{"id":"848b8dc6-758b-4bc7-93dd-c883de175ab8","content":"<p>The fossil, which is from the dicraeosaurid dinosaur group, is 167 million years old.</p>"}],"keys":["5212254d-2f96-4d48-a0ef-a3eb7d7518fe"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The sentence indicates where the dicraeosaurid fossil was found: western India&rsquo;s Thar Desert.</p><p>Choice B is incorrect. The sentence states that Bajpai&rsquo;s team discovered the dicraeosaurid fossil; it doesn&rsquo;t specify where they found it. Choice C is incorrect. The sentence provides information about Dr. Sunil Bajpai; it doesn&rsquo;t indicate where the fossil was found. Choice D is incorrect. While the sentence provides information about the fossil, it doesn&rsquo;t indicate where the fossil was found.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669206,"updateDate":1743430669206}$SATQ$::jsonb, 1743430669206, 1743430669206),
    ($SATQ$c78620ba$SATQ$, $SATQ$19d4a5b2-8ace-4094-99d6-23e73b86e4d9$SATQ$::uuid, $SATQ$5128f1a9-f584-4047-9a20-1326a0b98426$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>In 1968, US Congressman John Conyers introduced a bill to establish a national holiday in honor of Dr. Martin Luther King Jr. The bill didn&rsquo;t make it to a vote, but Conyers was determined. He teamed up with Shirley Chisholm, the first Black woman to be elected to Congress, and they resubmitted the bill every session for the next fifteen years. <span aria-hidden="true">______</span><span class="sr-only">blank</span> in 1983, the bill passed.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"fbed0719-8898-4442-81f6-5aa78a5f0796","content":"<p>Instead,</p>"},{"id":"14e0737c-7ff9-4ee3-a2cf-043d3f276682","content":"<p>Likewise,</p>"},{"id":"34422f07-83c5-40f7-b8fd-23612b7a2105","content":"<p>Finally,</p>"},{"id":"3143e5c3-3b28-412e-bf65-d45a2888c979","content":"<p>Additionally,</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["34422f07-83c5-40f7-b8fd-23612b7a2105"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. &ldquo;Finally&rdquo; logically signals that the bill passing&mdash;following many attempts between 1968 and 1983&mdash;is the final, concluding event in the sequence described in the previous sentences.&nbsp;</p><p>Choice A is incorrect because &ldquo;instead&rdquo; illogically signals that the bill passing is an alternative to one of the events described in the previous sentences. Instead, it is the final event in the sequence. Choice B is incorrect because &ldquo;likewise&rdquo; illogically signals that the bill passing is similar to one of the events described in the previous sentences. Instead, it is the final event in the sequence. Choice D is incorrect because &ldquo;additionally&rdquo; illogically signals that the bill passing is merely another event described along with the events of the previous sentences. Instead, it is the final, concluding event in the sequence. </p>$SATQ$, false, 0, $SATQ$OSP-229-TRA$SATQ$, $SATQ$$SATQ$, $SATQ$b9be0543-9cbf-407e-b7cd-99bd7764505d$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"c78620ba","external_id":"19d4a5b2-8ace-4094-99d6-23e73b86e4d9","vaultid":"5128f1a9-f584-4047-9a20-1326a0b98426","uId":"14eb2c92-a289-411b-9893-d99bf35b36e1","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>In 1968, US Congressman John Conyers introduced a bill to establish a national holiday in honor of Dr. Martin Luther King Jr. The bill didn&rsquo;t make it to a vote, but Conyers was determined. He teamed up with Shirley Chisholm, the first Black woman to be elected to Congress, and they resubmitted the bill every session for the next fifteen years. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> in 1983, the bill passed.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"fbed0719-8898-4442-81f6-5aa78a5f0796","content":"<p>Instead,</p>"},{"id":"14e0737c-7ff9-4ee3-a2cf-043d3f276682","content":"<p>Likewise,</p>"},{"id":"34422f07-83c5-40f7-b8fd-23612b7a2105","content":"<p>Finally,</p>"},{"id":"3143e5c3-3b28-412e-bf65-d45a2888c979","content":"<p>Additionally,</p>"}],"keys":["34422f07-83c5-40f7-b8fd-23612b7a2105"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. &ldquo;Finally&rdquo; logically signals that the bill passing&mdash;following many attempts between 1968 and 1983&mdash;is the final, concluding event in the sequence described in the previous sentences.&nbsp;</p><p>Choice A is incorrect because &ldquo;instead&rdquo; illogically signals that the bill passing is an alternative to one of the events described in the previous sentences. Instead, it is the final event in the sequence. Choice B is incorrect because &ldquo;likewise&rdquo; illogically signals that the bill passing is similar to one of the events described in the previous sentences. Instead, it is the final event in the sequence. Choice D is incorrect because &ldquo;additionally&rdquo; illogically signals that the bill passing is merely another event described along with the events of the previous sentences. Instead, it is the final, concluding event in the sequence. </p>","parenttemplatename":"OSP-229-TRA","parenttemplateid":"","templateclusterid":"b9be0543-9cbf-407e-b7cd-99bd7764505d","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959333,"updateDate":1691007959333}$SATQ$::jsonb, 1691007959333, 1691007959333),
    ($SATQ$c7e85c0a$SATQ$, $SATQ$04d33a0a-3907-4405-a6c8-c40b2fa56fcb$SATQ$::uuid, $SATQ$f3f365b4-9deb-444b-8e1b-c37b43c15a7d$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>The envelope-shaped paper bags common in the US 150 years ago were impractical for carrying goods. <span aria-hidden="true">______</span><span class="sr-only">blank</span> because they were the only paper bags that could be mass-produced, these bags dominated the market. That all changed in the 1870s, when industrial designer Margaret Knight patented a machine to make flat-bottomed, foldable paper bags.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"13984ae7-3004-45ba-a70f-7b993b3aae5c","content":"<p>However,</p>"},{"id":"75018042-a3e0-4943-b0d2-5d251f0ac666","content":"<p>For instance,</p>"},{"id":"461441a2-502a-49ce-8b35-5d604ae7ef14","content":"<p>Thus,</p>"},{"id":"8a24d2a8-7261-4074-92ab-fc814a6d719c","content":"<p>In other words,</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["13984ae7-3004-45ba-a70f-7b993b3aae5c"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. &ldquo;However&rdquo; logically signals that the information in this sentence&mdash;that envelope-shaped bags dominated the market&mdash;contrasts with the previous claim that these bags were impractical for carrying goods. </p><p>Choice B is incorrect because &ldquo;for instance&rdquo; illogically signals that the information in this sentence is an example supporting the previous claim that envelope-shaped bags were impractical for carrying goods. Instead, the sentence contrasts with the previous claim about the bags. Choice C is incorrect because &ldquo;thus&rdquo; illogically signals that the information in this sentence is a result of the previous claim that envelope-shaped bags were impractical for carrying goods. Instead, the sentence contrasts with the previous claim about the bags. Choice D is incorrect because &ldquo;in other words&rdquo; illogically signals that the information in this sentence is a paraphrase of the previous claim that envelope-shaped bags were impractical for carrying goods. Instead, the sentence contrasts with the previous claim about the bags. </p>$SATQ$, false, 0, $SATQ$OSP-264-TRA$SATQ$, $SATQ$$SATQ$, $SATQ$dad8e168-f1e5-408b-a4aa-c60654db4ad2$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"c7e85c0a","external_id":"04d33a0a-3907-4405-a6c8-c40b2fa56fcb","vaultid":"f3f365b4-9deb-444b-8e1b-c37b43c15a7d","uId":"627c125b-87d3-4f65-9719-5daeb84d9022","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>The envelope-shaped paper bags common in the US 150 years ago were impractical for carrying goods. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> because they were the only paper bags that could be mass-produced, these bags dominated the market. That all changed in the 1870s, when industrial designer Margaret Knight patented a machine to make flat-bottomed, foldable paper bags.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"13984ae7-3004-45ba-a70f-7b993b3aae5c","content":"<p>However,</p>"},{"id":"75018042-a3e0-4943-b0d2-5d251f0ac666","content":"<p>For instance,</p>"},{"id":"461441a2-502a-49ce-8b35-5d604ae7ef14","content":"<p>Thus,</p>"},{"id":"8a24d2a8-7261-4074-92ab-fc814a6d719c","content":"<p>In other words,</p>"}],"keys":["13984ae7-3004-45ba-a70f-7b993b3aae5c"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. &ldquo;However&rdquo; logically signals that the information in this sentence&mdash;that envelope-shaped bags dominated the market&mdash;contrasts with the previous claim that these bags were impractical for carrying goods. </p><p>Choice B is incorrect because &ldquo;for instance&rdquo; illogically signals that the information in this sentence is an example supporting the previous claim that envelope-shaped bags were impractical for carrying goods. Instead, the sentence contrasts with the previous claim about the bags. Choice C is incorrect because &ldquo;thus&rdquo; illogically signals that the information in this sentence is a result of the previous claim that envelope-shaped bags were impractical for carrying goods. Instead, the sentence contrasts with the previous claim about the bags. Choice D is incorrect because &ldquo;in other words&rdquo; illogically signals that the information in this sentence is a paraphrase of the previous claim that envelope-shaped bags were impractical for carrying goods. Instead, the sentence contrasts with the previous claim about the bags. </p>","parenttemplatename":"OSP-264-TRA","parenttemplateid":"","templateclusterid":"dad8e168-f1e5-408b-a4aa-c60654db4ad2","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959334,"updateDate":1691007959334}$SATQ$::jsonb, 1691007959334, 1691007959334),
    ($SATQ$c92ea686$SATQ$, $SATQ$b81c4ba9-46e3-4f71-bffa-f67533f258d1$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li><em>The Ramayana</em> is a Sanskrit epic poem from ancient India.</li>
<li>In <em>The Ramayana</em>, the character Kaikeyi is often portrayed as a villain.</li>
<li><em>Kaikeyi</em> is a 2022 novel by Vaishnavi Patel.</li>
<li>The novel is a retelling of the epic poem from Kaikeyi&rsquo;s point of view.</li>
<li>It often portrays Kaikeyi as heroic.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to emphasize whose point of view the novel is told from. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"aef66842-b6c2-4993-ad02-fd9c1eabb186","content":"<p>From the point of view of <em>The Ramayana</em>, the character Kaikeyi is often a villain.</p>"},{"id":"2128bff1-b639-49b2-a7de-cbc0b31df16b","content":"<p>Vaishnavi Patel often portrays the character as heroic.</p>"},{"id":"7940bd76-b855-4147-87d2-6f31b20bd91e","content":"<p><em>Kaikeyi</em> is a retelling of <em>The Ramayana</em> from the character Kaikeyi&rsquo;s point of view.</p>"},{"id":"7a04a533-c490-458c-a379-c918f9845530","content":"<p><em>The Ramayana</em> is an epic poem that features the character Kaikeyi.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["7940bd76-b855-4147-87d2-6f31b20bd91e"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The sentence emphasizes whose point of view the novel <em>Kaikeyi</em> is told from: the character Kaikeyi&rsquo;s.</p><p>Choice A is incorrect. While the sentence does discuss point of view, it focuses on that of the epic poem rather than the novel. Choice B is incorrect. While the sentence seems to be referring to Patel&rsquo;s novel, it doesn&rsquo;t establish whose point of view the novel is told from. Choice D is incorrect. The sentence discusses the character Kaikeyi in the context of the epic poem; it doesn&rsquo;t discuss the novel&rsquo;s point of view.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"c92ea686","external_id":"b81c4ba9-46e3-4f71-bffa-f67533f258d1","vaultid":null,"uId":"60a65a2e-ee8f-4fed-b4ec-c88262003f72","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li><em>The Ramayana</em> is a Sanskrit epic poem from ancient India.</li>\n<li>In <em>The Ramayana</em>, the character Kaikeyi is often portrayed as a villain.</li>\n<li><em>Kaikeyi</em> is a 2022 novel by Vaishnavi Patel.</li>\n<li>The novel is a retelling of the epic poem from Kaikeyi&rsquo;s point of view.</li>\n<li>It often portrays Kaikeyi as heroic.</li>\n</ul>","stem":"<p>The student wants to emphasize whose point of view the novel is told from. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"aef66842-b6c2-4993-ad02-fd9c1eabb186","content":"<p>From the point of view of <em>The Ramayana</em>, the character Kaikeyi is often a villain.</p>"},{"id":"2128bff1-b639-49b2-a7de-cbc0b31df16b","content":"<p>Vaishnavi Patel often portrays the character as heroic.</p>"},{"id":"7940bd76-b855-4147-87d2-6f31b20bd91e","content":"<p><em>Kaikeyi</em> is a retelling of <em>The Ramayana</em> from the character Kaikeyi&rsquo;s point of view.</p>"},{"id":"7a04a533-c490-458c-a379-c918f9845530","content":"<p><em>The Ramayana</em> is an epic poem that features the character Kaikeyi.</p>"}],"keys":["7940bd76-b855-4147-87d2-6f31b20bd91e"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The sentence emphasizes whose point of view the novel <em>Kaikeyi</em> is told from: the character Kaikeyi&rsquo;s.</p><p>Choice A is incorrect. While the sentence does discuss point of view, it focuses on that of the epic poem rather than the novel. Choice B is incorrect. While the sentence seems to be referring to Patel&rsquo;s novel, it doesn&rsquo;t establish whose point of view the novel is told from. Choice D is incorrect. The sentence discusses the character Kaikeyi in the context of the epic poem; it doesn&rsquo;t discuss the novel&rsquo;s point of view.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323035,"updateDate":1730147323035}$SATQ$::jsonb, 1730147323035, 1730147323035),
    ($SATQ$ca4ff52d$SATQ$, $SATQ$b9403057-54ab-4d5f-893d-98595e9d12e6$SATQ$::uuid, $SATQ$1afccb9f-4ea2-4ee0-8e59-219fe03b018c$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>Muslins are woven cotton fabrics with a variety of uses.</li>
<li>Dhaka muslin is a handmade fabric produced in Dhaka, Bangladesh.</li>
<li>It has an extremely fine weave and is primarily used to make luxury clothing.</li>
<li>Sheeting muslin is a machine-made fabric produced in factories.</li>
<li>It has a coarse weave and is primarily used to upholster furniture and create backdrops for theater sets.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to emphasize a difference between the two muslins. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"7af09a80-5e07-4ad0-8838-1965404c85fd","content":"<p>Dhaka muslin is a handmade fabric with an extremely fine weave, while sheeting muslin is machine made with a coarse weave.</p>"},{"id":"1129ee2d-32e2-49b9-a7f3-30942e22381c","content":"<p>Dhaka muslin and sheeting muslin are two different types of woven cotton fabrics.</p>"},{"id":"0b0a70ca-ece3-4fe3-a78b-c0b5c0453a42","content":"<p>Muslins can be used in a variety of ways, from making luxury clothing to upholstering furniture and creating backdrops for theater sets.</p>"},{"id":"48765144-927a-454f-af01-6dd58b7d4f71","content":"<p>Sheeting muslin is machine made, has a coarse weave, and is used for furniture and theater sets.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["7af09a80-5e07-4ad0-8838-1965404c85fd"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The difference between the two different kinds of muslin is emphasized. </p><p>Choice B is incorrect. This choice lists two kinds of muslins, but does not say how they are different from one another. Choice C is incorrect. This choice does not emphasize a difference between the two muslins. Choice D is incorrect. This choice does not emphasize a difference between the two muslins. It only describes sheeting muslin. </p>$SATQ$, false, 0, $SATQ$OSP-KA-SYN-M002$SATQ$, $SATQ$$SATQ$, $SATQ$5eedf4eb-d078-4588-a375-03f766606fad$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"ca4ff52d","external_id":"b9403057-54ab-4d5f-893d-98595e9d12e6","vaultid":"1afccb9f-4ea2-4ee0-8e59-219fe03b018c","uId":"18672d06-1099-443e-b201-6283da936308","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>Muslins are woven cotton fabrics with a variety of uses.</li>\n<li>Dhaka muslin is a handmade fabric produced in Dhaka, Bangladesh.</li>\n<li>It has an extremely fine weave and is primarily used to make luxury clothing.</li>\n<li>Sheeting muslin is a machine-made fabric produced in factories.</li>\n<li>It has a coarse weave and is primarily used to upholster furniture and create backdrops for theater sets.</li>\n</ul>","stem":"<p>The student wants to emphasize a difference between the two muslins. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"7af09a80-5e07-4ad0-8838-1965404c85fd","content":"<p>Dhaka muslin is a handmade fabric with an extremely fine weave, while sheeting muslin is machine made with a coarse weave.</p>"},{"id":"1129ee2d-32e2-49b9-a7f3-30942e22381c","content":"<p>Dhaka muslin and sheeting muslin are two different types of woven cotton fabrics.</p>"},{"id":"0b0a70ca-ece3-4fe3-a78b-c0b5c0453a42","content":"<p>Muslins can be used in a variety of ways, from making luxury clothing to upholstering furniture and creating backdrops for theater sets.</p>"},{"id":"48765144-927a-454f-af01-6dd58b7d4f71","content":"<p>Sheeting muslin is machine made, has a coarse weave, and is used for furniture and theater sets.</p>"}],"keys":["7af09a80-5e07-4ad0-8838-1965404c85fd"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The difference between the two different kinds of muslin is emphasized. </p><p>Choice B is incorrect. This choice lists two kinds of muslins, but does not say how they are different from one another. Choice C is incorrect. This choice does not emphasize a difference between the two muslins. Choice D is incorrect. This choice does not emphasize a difference between the two muslins. It only describes sheeting muslin. </p>","parenttemplatename":"OSP-KA-SYN-M002","parenttemplateid":"","templateclusterid":"5eedf4eb-d078-4588-a375-03f766606fad","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959372,"updateDate":1691007959372}$SATQ$::jsonb, 1691007959372, 1691007959372),
    ($SATQ$ce282575$SATQ$, $SATQ$aa3dfb75-0ee8-4337-83bc-1c75b6940fd6$SATQ$::uuid, $SATQ$f1b650bd-34c1-423d-987f-8962707b8933$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>J.R.R. Tolkien&rsquo;s 1937 novel <em>The Hobbit </em>features two maps.</li>
<li>The novel opens with a reproduction of the map that the characters use on their quest.</li>
<li>This map introduces readers to the fictional world they are about to enter.</li>
<li>The novel closes with a map depicting every stop on the characters&rsquo; journey.</li>
<li>That map allows readers to reconstruct the story they have just read.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to contrast the purposes of the two maps in <em>The Hobbit</em>. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"d744e523-2c05-4618-baf2-40802b12e9d5","content":"<p><em>The Hobbit</em>&rsquo;s opening map introduces readers to the fictional world they are about to enter, while the closing map allows them to reconstruct the story they have just read.</p>"},{"id":"2c4f903c-3275-482d-88af-0cbe5a9a2cf4","content":"<p><em>The Hobbit</em>, a novel published by J.R.R. Tolkien in 1937, features a reproduction of a map that the characters use on their quest, as well as a map that appears at the end of the novel.</p>"},{"id":"a4ebf0b3-1e14-43ca-848b-89aa8fe29241","content":"<p><em>The Hobbit</em>&rsquo;s two maps, one opening and one closing the novel, each serve a purpose for readers.</p>"},{"id":"51e492ea-613b-4bea-a0cb-21cf0a59f4e4","content":"<p>In 1937, author J.R.R. Tolkien published <em>The Hobbit</em>, a novel featuring both an opening and a closing map.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["d744e523-2c05-4618-baf2-40802b12e9d5"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The sentence contrasts the purposes of the two maps in <em>The Hobbit</em>, noting that the opening map introduces readers to the book&rsquo;s fictional world, while the closing map helps readers reconstruct the story. The word &ldquo;while&rdquo; helps signal a contrast between the purposes of the maps.&nbsp;</p><p>Choice B is incorrect. While the sentence mentions the two maps, it doesn&rsquo;t contrast the maps&rsquo; purposes. Choice C is incorrect. While the sentence mentions the two maps and notes that each has a purpose, it doesn&rsquo;t specify what those purposes are or how they contrast.&nbsp;Choice D is incorrect. While the sentence mentions the two maps, it doesn&rsquo;t contrast the maps&rsquo; purposes. </p>$SATQ$, false, 0, $SATQ$OSP-770-SYN$SATQ$, $SATQ$$SATQ$, $SATQ$cdf18d04-2b27-4ff1-b992-102076a22573$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"ce282575","external_id":"aa3dfb75-0ee8-4337-83bc-1c75b6940fd6","vaultid":"f1b650bd-34c1-423d-987f-8962707b8933","uId":"b56b4531-97f8-46d3-bfb7-fa8eb7128016","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>J.R.R. Tolkien&rsquo;s 1937 novel <em>The Hobbit </em>features two maps.</li>\n<li>The novel opens with a reproduction of the map that the characters use on their quest.</li>\n<li>This map introduces readers to the fictional world they are about to enter.</li>\n<li>The novel closes with a map depicting every stop on the characters&rsquo; journey.</li>\n<li>That map allows readers to reconstruct the story they have just read.</li>\n</ul>","stem":"<p>The student wants to contrast the purposes of the two maps in <em>The Hobbit</em>. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"d744e523-2c05-4618-baf2-40802b12e9d5","content":"<p><em>The Hobbit</em>&rsquo;s opening map introduces readers to the fictional world they are about to enter, while the closing map allows them to reconstruct the story they have just read.</p>"},{"id":"2c4f903c-3275-482d-88af-0cbe5a9a2cf4","content":"<p><em>The Hobbit</em>, a novel published by J.R.R. Tolkien in 1937, features a reproduction of a map that the characters use on their quest, as well as a map that appears at the end of the novel.</p>"},{"id":"a4ebf0b3-1e14-43ca-848b-89aa8fe29241","content":"<p><em>The Hobbit</em>&rsquo;s two maps, one opening and one closing the novel, each serve a purpose for readers.</p>"},{"id":"51e492ea-613b-4bea-a0cb-21cf0a59f4e4","content":"<p>In 1937, author J.R.R. Tolkien published <em>The Hobbit</em>, a novel featuring both an opening and a closing map.</p>"}],"keys":["d744e523-2c05-4618-baf2-40802b12e9d5"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The sentence contrasts the purposes of the two maps in <em>The Hobbit</em>, noting that the opening map introduces readers to the book&rsquo;s fictional world, while the closing map helps readers reconstruct the story. The word &ldquo;while&rdquo; helps signal a contrast between the purposes of the maps.&nbsp;</p><p>Choice B is incorrect. While the sentence mentions the two maps, it doesn&rsquo;t contrast the maps&rsquo; purposes. Choice C is incorrect. While the sentence mentions the two maps and notes that each has a purpose, it doesn&rsquo;t specify what those purposes are or how they contrast.&nbsp;Choice D is incorrect. While the sentence mentions the two maps, it doesn&rsquo;t contrast the maps&rsquo; purposes. </p>","parenttemplatename":"OSP-770-SYN","parenttemplateid":"","templateclusterid":"cdf18d04-2b27-4ff1-b992-102076a22573","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959352,"updateDate":1691007959352}$SATQ$::jsonb, 1691007959352, 1691007959352),
    ($SATQ$cf11282b$SATQ$, $SATQ$4d4c8dd9-5100-47fc-b73a-cd0e64a682fb$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>Scientists were able to isolate a relatively pure sample of selenium in 1817, the same year they first discovered the element&rsquo;s existence. <span aria-hidden="true">______</span><span class="sr-only">blank</span> the isolation process took longer for molybdenum, which was isolated in its pure form three years after scientists first discovered it.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"6b0459fb-bc9a-4978-a074-79be7980cfca","content":"<p>By contrast,</p>"},{"id":"be59d74e-9255-44cc-94a1-8854aa9f05d3","content":"<p>Thus,</p>"},{"id":"8ed2b478-7fa1-49b0-afd2-c37001ceb323","content":"<p>Similarly,</p>"},{"id":"c9752522-352d-40db-b9b5-3e82985ee7cd","content":"<p>For instance,</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["6b0459fb-bc9a-4978-a074-79be7980cfca"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. "By contrast" logically signals that the information in this sentence&mdash;that isolating molybdenum was a relatively long process&mdash;contrasts with the previous information that isolating selenium was a short process.</p><p>Choice B is incorrect because "thus" illogically signals that the information in this sentence is a result of the previous information about selenium&rsquo;s short isolation process. Instead, the sentence presents contrasting information about molybdenum&rsquo;s longer isolation process. Choice C is incorrect because "similarly" illogically signals that the information in this sentence is similar to the previous information about selenium&rsquo;s short isolation process. Instead, the sentence presents contrasting information about molybdenum&rsquo;s longer isolation process. Choice D is incorrect because "for instance" illogically signals that the information in this sentence exemplifies the previous information about selenium&rsquo;s short isolation process. Instead, the sentence presents contrasting information about molybdenum&rsquo;s longer isolation process.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"cf11282b","external_id":"4d4c8dd9-5100-47fc-b73a-cd0e64a682fb","vaultid":null,"uId":"0b232302-e666-4112-9e2d-993c80cfc2d6","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>Scientists were able to isolate a relatively pure sample of selenium in 1817, the same year they first discovered the element&rsquo;s existence. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> the isolation process took longer for molybdenum, which was isolated in its pure form three years after scientists first discovered it.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"6b0459fb-bc9a-4978-a074-79be7980cfca","content":"<p>By contrast,</p>"},{"id":"be59d74e-9255-44cc-94a1-8854aa9f05d3","content":"<p>Thus,</p>"},{"id":"8ed2b478-7fa1-49b0-afd2-c37001ceb323","content":"<p>Similarly,</p>"},{"id":"c9752522-352d-40db-b9b5-3e82985ee7cd","content":"<p>For instance,</p>"}],"keys":["6b0459fb-bc9a-4978-a074-79be7980cfca"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. \"By contrast\" logically signals that the information in this sentence&mdash;that isolating molybdenum was a relatively long process&mdash;contrasts with the previous information that isolating selenium was a short process.</p><p>Choice B is incorrect because \"thus\" illogically signals that the information in this sentence is a result of the previous information about selenium&rsquo;s short isolation process. Instead, the sentence presents contrasting information about molybdenum&rsquo;s longer isolation process. Choice C is incorrect because \"similarly\" illogically signals that the information in this sentence is similar to the previous information about selenium&rsquo;s short isolation process. Instead, the sentence presents contrasting information about molybdenum&rsquo;s longer isolation process. Choice D is incorrect because \"for instance\" illogically signals that the information in this sentence exemplifies the previous information about selenium&rsquo;s short isolation process. Instead, the sentence presents contrasting information about molybdenum&rsquo;s longer isolation process.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061177,"updateDate":1755117061177}$SATQ$::jsonb, 1755117061177, 1755117061177),
    ($SATQ$cfade68d$SATQ$, $SATQ$3b0557c9-cb2e-4757-ac8b-73a2f43694cb$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes: &nbsp;</p>
<ul>
<li>Marcela Guerrero is a curator at the Whitney Museum of American Art in New York.&nbsp;</li>
<li>She curated the Whitney&rsquo;s 2018 exhibition <em>Pacha, Llaqta, Wasichay: Indigenous Space, Modern Architecture, New Art</em>.</li>
<li>This exhibition featured works by seven emerging Latino artists.</li>
<li>She curated the Whitney&rsquo;s 2020 exhibition <em>Vida Americana: Mexican Muralists Remake American Art, 1925&ndash;1945</em>.</li>
<li>This exhibition included nearly 200 works by twentieth-century Latino and Mexican artists.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to describe the exhibition that Guerrero curated in 2018. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"d96a22ae-0971-4385-93ee-9042fe2f89f9","content":"<p>Held at the Whitney Museum of American Art, the exhibition <em>Vida Americana: Mexican Muralists Remake American Art, 1925&ndash;1945</em> included nearly 200 works by twentieth-century Mexican and Latino artists.</p>"},{"id":"fec8a616-92f6-4b29-a0b2-903d0c47a013","content":"<p><em>Pacha, Llaqta, Wasichay: Indigenous Space, Modern Architecture, New Art</em>, an exhibition at the Whitney Museum of American Art, featured works by seven emerging Latino artists.&nbsp;</p>"},{"id":"081e5ab7-1c6e-4ebd-b8b9-996267e25e61","content":"<p>In both 2018 and 2020, Marcela Guerrero curated exhibitions at the Whitney Museum of American Art in New York.</p>"},{"id":"41d8d290-b0c3-4199-a927-812994171738","content":"<p>While one exhibition that Marcela Guerrero curated featured works by emerging artists, another included works by twentieth-century artists.&nbsp;</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["fec8a616-92f6-4b29-a0b2-903d0c47a013"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The sentence describes the 2018 exhibition Guerrero curated, noting that the exhibition, which was titled <em>Pacha, Llaqta, Wasichay: Indigenous Space, Modern Architecture, New Art</em>, featured the works of seven emerging Latino artists.</p><p>Choice A is incorrect. The sentence describes the exhibition Guerrero curated in 2020; it doesn&rsquo;t describe her 2018 exhibition. Choice C is incorrect. The sentence emphasizes a similarity between the two exhibitions Guerrero curated; it doesn&rsquo;t describe her 2018 exhibition. Choice D is incorrect. The sentence emphasizes a difference between the two exhibitions Guerrero curated; it doesn&rsquo;t describe her 2018 exhibition.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"cfade68d","external_id":"3b0557c9-cb2e-4757-ac8b-73a2f43694cb","vaultid":null,"uId":"89b0048b-214a-4020-af80-d0b2529a179e","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes: &nbsp;</p>\n<ul>\n<li>Marcela Guerrero is a curator at the Whitney Museum of American Art in New York.&nbsp;</li>\n<li>She curated the Whitney&rsquo;s 2018 exhibition <em>Pacha, Llaqta, Wasichay: Indigenous Space, Modern Architecture, New Art</em>.</li>\n<li>This exhibition featured works by seven emerging Latino artists.</li>\n<li>She curated the Whitney&rsquo;s 2020 exhibition <em>Vida Americana: Mexican Muralists Remake American Art, 1925&ndash;1945</em>.</li>\n<li>This exhibition included nearly 200 works by twentieth-century Latino and Mexican artists.</li>\n</ul>","stem":"<p>The student wants to describe the exhibition that Guerrero curated in 2018. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"d96a22ae-0971-4385-93ee-9042fe2f89f9","content":"<p>Held at the Whitney Museum of American Art, the exhibition <em>Vida Americana: Mexican Muralists Remake American Art, 1925&ndash;1945</em> included nearly 200 works by twentieth-century Mexican and Latino artists.</p>"},{"id":"fec8a616-92f6-4b29-a0b2-903d0c47a013","content":"<p><em>Pacha, Llaqta, Wasichay: Indigenous Space, Modern Architecture, New Art</em>, an exhibition at the Whitney Museum of American Art, featured works by seven emerging Latino artists.&nbsp;</p>"},{"id":"081e5ab7-1c6e-4ebd-b8b9-996267e25e61","content":"<p>In both 2018 and 2020, Marcela Guerrero curated exhibitions at the Whitney Museum of American Art in New York.</p>"},{"id":"41d8d290-b0c3-4199-a927-812994171738","content":"<p>While one exhibition that Marcela Guerrero curated featured works by emerging artists, another included works by twentieth-century artists.&nbsp;</p>"}],"keys":["fec8a616-92f6-4b29-a0b2-903d0c47a013"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The sentence describes the 2018 exhibition Guerrero curated, noting that the exhibition, which was titled <em>Pacha, Llaqta, Wasichay: Indigenous Space, Modern Architecture, New Art</em>, featured the works of seven emerging Latino artists.</p><p>Choice A is incorrect. The sentence describes the exhibition Guerrero curated in 2020; it doesn&rsquo;t describe her 2018 exhibition. Choice C is incorrect. The sentence emphasizes a similarity between the two exhibitions Guerrero curated; it doesn&rsquo;t describe her 2018 exhibition. Choice D is incorrect. The sentence emphasizes a difference between the two exhibitions Guerrero curated; it doesn&rsquo;t describe her 2018 exhibition.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323035,"updateDate":1730147323035}$SATQ$::jsonb, 1730147323035, 1730147323035),
    ($SATQ$d10e46a2$SATQ$, $SATQ$e8fb16ed-2885-4d57-a2c3-b457ffb72355$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>The ancient Spartans were known for their bitingly concise&mdash;or laconic&mdash;wit, a quality they maintained even in the face of great peril. <span aria-hidden="true">______</span><span class="sr-only">blank</span> when Philip II of Macedon threatened Laconia (the region of Greece containing Sparta), he said, &ldquo;If I invade Laconia, I shall turn you out.&rdquo; The Spartans replied with a single word: &ldquo;If.&rdquo;</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"afe38a5d-985e-4fc8-9c9b-91901998bbe5","content":"<p>Rather,</p>"},{"id":"7b154847-218b-4e5a-97d7-83a081714646","content":"<p>In other words,</p>"},{"id":"c650fa1a-e2d5-4755-85f8-3e92af7950ee","content":"<p>That said,</p>"},{"id":"28db6761-fcf4-4d36-ac45-6e47177f660a","content":"<p>For instance,</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["28db6761-fcf4-4d36-ac45-6e47177f660a"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. "For instance" logically signals that the concise, witty exchange between Philip II and the Spartans is an example supporting the previous claim&mdash;that the Spartans employed wit even in the face of peril.</p><p>Choice A is incorrect because "rather" illogically signals that the exchange between Philip II and the Spartans contrasts with the previous claim about the Spartans&rsquo; wit. Instead, the exchange is an example of their wit. Choice B is incorrect because "in other words" illogically signals that the exchange between Philip II and the Spartans is a restatement of the previous claim about the Spartans&rsquo; wit. Instead, the exchange is an example of their wit. Choice C is incorrect because "that said" illogically signals that the exchange between Philip II and the Spartans is an exception to the previous claim about the Spartans&rsquo; wit. Instead, the exchange is an example of their wit.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"d10e46a2","external_id":"e8fb16ed-2885-4d57-a2c3-b457ffb72355","vaultid":null,"uId":"732448ea-007a-4446-88a4-ff999445004b","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>The ancient Spartans were known for their bitingly concise&mdash;or laconic&mdash;wit, a quality they maintained even in the face of great peril. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> when Philip II of Macedon threatened Laconia (the region of Greece containing Sparta), he said, &ldquo;If I invade Laconia, I shall turn you out.&rdquo; The Spartans replied with a single word: &ldquo;If.&rdquo;</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"afe38a5d-985e-4fc8-9c9b-91901998bbe5","content":"<p>Rather,</p>"},{"id":"7b154847-218b-4e5a-97d7-83a081714646","content":"<p>In other words,</p>"},{"id":"c650fa1a-e2d5-4755-85f8-3e92af7950ee","content":"<p>That said,</p>"},{"id":"28db6761-fcf4-4d36-ac45-6e47177f660a","content":"<p>For instance,</p>"}],"keys":["28db6761-fcf4-4d36-ac45-6e47177f660a"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. \"For instance\" logically signals that the concise, witty exchange between Philip II and the Spartans is an example supporting the previous claim&mdash;that the Spartans employed wit even in the face of peril.</p><p>Choice A is incorrect because \"rather\" illogically signals that the exchange between Philip II and the Spartans contrasts with the previous claim about the Spartans&rsquo; wit. Instead, the exchange is an example of their wit. Choice B is incorrect because \"in other words\" illogically signals that the exchange between Philip II and the Spartans is a restatement of the previous claim about the Spartans&rsquo; wit. Instead, the exchange is an example of their wit. Choice C is incorrect because \"that said\" illogically signals that the exchange between Philip II and the Spartans is an exception to the previous claim about the Spartans&rsquo; wit. Instead, the exchange is an example of their wit.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323042,"updateDate":1730147323042}$SATQ$::jsonb, 1730147323042, 1730147323042),
    ($SATQ$d2b52c50$SATQ$, $SATQ$4b7d0253-1216-4e18-92df-dc50b1c6d4c6$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:&nbsp;</p>
<ul>
<li>On January 3, 1959, Alaska became the 49th state to join the US.&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</li>
<li>On August 21, 1959, Hawaii became the 50th state to join the US.&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</li>
<li>A new 50-star US flag was unveiled the same day.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to emphasize the order in which Alaska and Hawaii became US states. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"8d489b26-a15b-4d67-a24c-db541fa2adc3","content":"<p>Alaska, the 49th US state, became a state several months before Hawaii, the 50th state, did.</p>"},{"id":"e8eb8bf5-bf3f-453f-a2e0-ad102788e9bd","content":"<p>On August 21, 1959, a new 50-star US flag was unveiled.</p>"},{"id":"517d65c3-937f-4efd-9399-d3de047e2e12","content":"<p>The 49th and 50th states to join the US did so in the same year.</p>"},{"id":"e2cd6952-a7dc-4a99-a3f6-c5c8fcab98e6","content":"<p>The same day that Hawaii became a US state&mdash;August 21, 1959&mdash;a new US flag was unveiled.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["8d489b26-a15b-4d67-a24c-db541fa2adc3"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The sentence emphasizes the order in which Alaska and Hawaii became US states, noting that Alaska became a US state several months before Hawaii did.</p><p>Choice B is incorrect. The sentence specifies when the 50-star US flag was unveiled; it doesn&rsquo;t emphasize the order in which Alaska and Hawaii became US states. Choice C is incorrect. While the sentence indicates that the 49th and 50th states became US states in the same year, it doesn&rsquo;t identify which state was the 49th and which was the 50th; as a result, it doesn&rsquo;t emphasize the order in which Alaska and Hawaii became states. Choice D is incorrect. The sentence indicates that a new US flag was unveiled when Hawaii became a US state; it doesn&rsquo;t emphasize the order in which Alaska and Hawaii became states.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"d2b52c50","external_id":"4b7d0253-1216-4e18-92df-dc50b1c6d4c6","vaultid":null,"uId":"7a84fed1-b2a6-44ce-a1f0-16eee662c59b","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:&nbsp;</p>\n<ul>\n<li>On January 3, 1959, Alaska became the 49th state to join the US.&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</li>\n<li>On August 21, 1959, Hawaii became the 50th state to join the US.&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</li>\n<li>A new 50-star US flag was unveiled the same day.</li>\n</ul>","stem":"<p>The student wants to emphasize the order in which Alaska and Hawaii became US states. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"8d489b26-a15b-4d67-a24c-db541fa2adc3","content":"<p>Alaska, the 49th US state, became a state several months before Hawaii, the 50th state, did.</p>"},{"id":"e8eb8bf5-bf3f-453f-a2e0-ad102788e9bd","content":"<p>On August 21, 1959, a new 50-star US flag was unveiled.</p>"},{"id":"517d65c3-937f-4efd-9399-d3de047e2e12","content":"<p>The 49th and 50th states to join the US did so in the same year.</p>"},{"id":"e2cd6952-a7dc-4a99-a3f6-c5c8fcab98e6","content":"<p>The same day that Hawaii became a US state&mdash;August 21, 1959&mdash;a new US flag was unveiled.</p>"}],"keys":["8d489b26-a15b-4d67-a24c-db541fa2adc3"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The sentence emphasizes the order in which Alaska and Hawaii became US states, noting that Alaska became a US state several months before Hawaii did.</p><p>Choice B is incorrect. The sentence specifies when the 50-star US flag was unveiled; it doesn&rsquo;t emphasize the order in which Alaska and Hawaii became US states. Choice C is incorrect. While the sentence indicates that the 49th and 50th states became US states in the same year, it doesn&rsquo;t identify which state was the 49th and which was the 50th; as a result, it doesn&rsquo;t emphasize the order in which Alaska and Hawaii became states. Choice D is incorrect. The sentence indicates that a new US flag was unveiled when Hawaii became a US state; it doesn&rsquo;t emphasize the order in which Alaska and Hawaii became states.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669206,"updateDate":1743430669206}$SATQ$::jsonb, 1743430669206, 1743430669206),
    ($SATQ$d3725911$SATQ$, $SATQ$556b6a32-dc40-4eec-96c0-5389bcae5626$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>In the search for extraterrestrial life, astrobiologists Stuart Bartlett and Michael L. Wong propose that scientists avoid using the term &ldquo;life.&rdquo; <span aria-hidden="true">______</span><span class="sr-only">blank</span> researchers should use another word: &ldquo;lyfe.&rdquo; This new term, they argue, could be used to draw distinctions between the known characteristics of life on Earth and the potentially differing characteristics of lyfe on other planets.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"7898d576-ebe7-4877-99a0-b3c56b580653","content":"<p>Previously,</p>"},{"id":"94b71a0a-c91d-47e4-a8ce-470afae312b7","content":"<p>Regardless,</p>"},{"id":"c48d63ff-a4af-425c-8e70-66d0715dc818","content":"<p>There,</p>"},{"id":"e82bc787-c63d-4bbb-8914-bea0b8abaf2d","content":"<p>Instead,</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["e82bc787-c63d-4bbb-8914-bea0b8abaf2d"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. "Instead" logically signals that the idea in this sentence&mdash;that researchers should use the word "lyfe"&mdash;is an alternative to the idea mentioned in the previous sentence (scientists&rsquo; use of the word "life").</p><p>Choice A is incorrect because "previously" illogically signals that the idea in this sentence occurs before the action in the first sentence. Instead, the use of "lyfe" is an alternative to the previously mentioned use of "life." Choice B is incorrect because "regardless" illogically signals that the idea in this sentence is true despite the information in the first sentence. Instead, the use of "lyfe" is an alternative to the previously mentioned use of "life." Choice C is incorrect because "there" illogically signals that the idea in this sentence occurs in a place mentioned in the previous sentence. Instead, the use of "lyfe" is an alternative to the previously mentioned use of "life."</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"d3725911","external_id":"556b6a32-dc40-4eec-96c0-5389bcae5626","vaultid":null,"uId":"89c5da51-d679-406c-b7a8-6403d1315ecc","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>In the search for extraterrestrial life, astrobiologists Stuart Bartlett and Michael L. Wong propose that scientists avoid using the term &ldquo;life.&rdquo; <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> researchers should use another word: &ldquo;lyfe.&rdquo; This new term, they argue, could be used to draw distinctions between the known characteristics of life on Earth and the potentially differing characteristics of lyfe on other planets.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"7898d576-ebe7-4877-99a0-b3c56b580653","content":"<p>Previously,</p>"},{"id":"94b71a0a-c91d-47e4-a8ce-470afae312b7","content":"<p>Regardless,</p>"},{"id":"c48d63ff-a4af-425c-8e70-66d0715dc818","content":"<p>There,</p>"},{"id":"e82bc787-c63d-4bbb-8914-bea0b8abaf2d","content":"<p>Instead,</p>"}],"keys":["e82bc787-c63d-4bbb-8914-bea0b8abaf2d"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. \"Instead\" logically signals that the idea in this sentence&mdash;that researchers should use the word \"lyfe\"&mdash;is an alternative to the idea mentioned in the previous sentence (scientists&rsquo; use of the word \"life\").</p><p>Choice A is incorrect because \"previously\" illogically signals that the idea in this sentence occurs before the action in the first sentence. Instead, the use of \"lyfe\" is an alternative to the previously mentioned use of \"life.\" Choice B is incorrect because \"regardless\" illogically signals that the idea in this sentence is true despite the information in the first sentence. Instead, the use of \"lyfe\" is an alternative to the previously mentioned use of \"life.\" Choice C is incorrect because \"there\" illogically signals that the idea in this sentence occurs in a place mentioned in the previous sentence. Instead, the use of \"lyfe\" is an alternative to the previously mentioned use of \"life.\"</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323043,"updateDate":1730147323043}$SATQ$::jsonb, 1730147323043, 1730147323043),
    ($SATQ$d3898d32$SATQ$, $SATQ$fa2d1a26-46bd-490d-8fe1-30454adad22a$SATQ$::uuid, $SATQ$51e94bf9-f7e3-4259-917a-af7499f47caa$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>Riley Black&mdash;the author of critically acclaimed books such as <em>My Beloved Brontosaurus</em> (2013)&mdash;is best known for writing about dinosaurs, but she has also conducted hands-on fieldwork. <span aria-hidden="true">______</span><span class="sr-only">blank</span> her fieldwork has included paleontological digs in Utah, Montana, and Wyoming, and her dinosaur fossil discoveries can be seen at places such as the Carnegie Museum of Natural History.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"32a32ad3-728b-49bc-96fe-dc9edeb6ab9b","content":"<p>Regardless,&nbsp;</p>"},{"id":"c3abb5b7-dc1a-4aa0-8f36-41404ff0d160","content":"<p>Subsequently,</p>"},{"id":"58e1022b-1edb-4adb-830e-d3fff82cf6ab","content":"<p>Specifically,&nbsp;</p>"},{"id":"e09ef35a-2a57-4baf-8e9e-59ecf1e8f97a","content":"<p>Conversely,</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["58e1022b-1edb-4adb-830e-d3fff82cf6ab"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The second sentence provides more specific information about the fieldwork mentioned in the first sentence&mdash;that the paleontological digs took place in Utah, Montana, and Wyoming. Therefore, &ldquo;specifically&rdquo; fits perfectly in this context. </p><p>Choice A is incorrect. This choice uses a disagreement transition. But this sentence doesn&rsquo;t disagree with the previous sentence. Rather, this sentence agrees with and elaborates on the last sentence by providing more specifics about the fieldwork Black does. Choice B is incorrect. This choice uses a transition that indicates that an event took place after another event. But the two sentences are not describing different events&mdash;instead, this sentence gives more details about the fieldwork discussed in the first sentence. Choice D is incorrect. This choice uses a disagreement transition. But this sentence doesn&rsquo;t disagree with the previous sentence. Rather, this sentence agrees with and elaborates on the last sentence by providing more specifics about the fieldwork Black does. </p>$SATQ$, false, 0, $SATQ$OSP-KA-TRA-E010$SATQ$, $SATQ$$SATQ$, $SATQ$b2e72c76-9323-47c4-b82c-bc58235395a7$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"d3898d32","external_id":"fa2d1a26-46bd-490d-8fe1-30454adad22a","vaultid":"51e94bf9-f7e3-4259-917a-af7499f47caa","uId":"ee14dbac-b013-48aa-9327-61a82306ed44","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>Riley Black&mdash;the author of critically acclaimed books such as <em>My Beloved Brontosaurus</em> (2013)&mdash;is best known for writing about dinosaurs, but she has also conducted hands-on fieldwork. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> her fieldwork has included paleontological digs in Utah, Montana, and Wyoming, and her dinosaur fossil discoveries can be seen at places such as the Carnegie Museum of Natural History.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"32a32ad3-728b-49bc-96fe-dc9edeb6ab9b","content":"<p>Regardless,&nbsp;</p>"},{"id":"c3abb5b7-dc1a-4aa0-8f36-41404ff0d160","content":"<p>Subsequently,</p>"},{"id":"58e1022b-1edb-4adb-830e-d3fff82cf6ab","content":"<p>Specifically,&nbsp;</p>"},{"id":"e09ef35a-2a57-4baf-8e9e-59ecf1e8f97a","content":"<p>Conversely,</p>"}],"keys":["58e1022b-1edb-4adb-830e-d3fff82cf6ab"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The second sentence provides more specific information about the fieldwork mentioned in the first sentence&mdash;that the paleontological digs took place in Utah, Montana, and Wyoming. Therefore, &ldquo;specifically&rdquo; fits perfectly in this context. </p><p>Choice A is incorrect. This choice uses a disagreement transition. But this sentence doesn&rsquo;t disagree with the previous sentence. Rather, this sentence agrees with and elaborates on the last sentence by providing more specifics about the fieldwork Black does. Choice B is incorrect. This choice uses a transition that indicates that an event took place after another event. But the two sentences are not describing different events&mdash;instead, this sentence gives more details about the fieldwork discussed in the first sentence. Choice D is incorrect. This choice uses a disagreement transition. But this sentence doesn&rsquo;t disagree with the previous sentence. Rather, this sentence agrees with and elaborates on the last sentence by providing more specifics about the fieldwork Black does. </p>","parenttemplatename":"OSP-KA-TRA-E010","parenttemplateid":"","templateclusterid":"b2e72c76-9323-47c4-b82c-bc58235395a7","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959373,"updateDate":1691007959373}$SATQ$::jsonb, 1691007959373, 1691007959373),
    ($SATQ$d3b7d7a3$SATQ$, $SATQ$87812ea4-9d3b-4381-9f09-9e3b8c2ea327$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>Many historical accounts of the 1930s focus on the widespread movement of people from dust bowl&ndash;ravaged Great Plains states to faraway California. However, a <span data-ssml-say-as="date">2016</span> study of <span data-ssml-say-as="date">1940</span> census data complicates this popular narrative; <span aria-hidden="true">______</span><span class="sr-only">blank</span> researchers determined, migrants in states hardest hit by prolonged droughts and dust storms&mdash;Colorado, Kansas, Oklahoma, and Texas&mdash;merely relocated within the region.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"b808790a-dc64-4064-8ecb-ddd7ac0ea268","content":"<p>for this reason,</p>"},{"id":"7f906209-c0fc-46ac-8b9e-0203c94e6f4c","content":"<p>more often,</p>"},{"id":"b53a748c-a813-4bf1-ae7f-fe931674217d","content":"<p>additionally,</p>"},{"id":"ff620934-9a41-472e-9977-4c7b22c66b7d","content":"<p>nevertheless,</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["7f906209-c0fc-46ac-8b9e-0203c94e6f4c"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. &ldquo;More often&rdquo; logically signals that the historical outcome in this clause&mdash;dust bowl migrants&rsquo; relocation within the Great Plains region&mdash;was more common than the movement to California described in many historical accounts.</p><p>Choice A is incorrect because &ldquo;for this reason&rdquo; illogically signals that the historical outcome in this clause was caused by either the narrative about widespread movement to California or the 2016 study&rsquo;s complication of that narrative. Instead, dust bowl migrants&rsquo; regional relocation was found to be more common than the movement to California described in many historical accounts. Choice C is incorrect because &ldquo;additionally&rdquo; illogically signals that the historical outcome in this clause merely adds to either the narrative about widespread movement to California or the 2016 study&rsquo;s complication of that narrative. Instead, dust bowl migrants&rsquo; regional relocation was found to be more common than the movement to California described in many historical accounts. Choice D is incorrect because &ldquo;nevertheless&rdquo; illogically signals that the historical outcome in this clause is true despite either the narrative about widespread movement to California or the 2016 study&rsquo;s complication of that narrative. While the findings about dust bowl migrants&rsquo; regional relocation did challenge the previous narrative, they did not challenge the study&rsquo;s findings, and this choice creates a confusing ambiguity. Instead, dust bowl migrants&rsquo; regional relocation was found to be more common than the movement to California described in many historical accounts.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"d3b7d7a3","external_id":"87812ea4-9d3b-4381-9f09-9e3b8c2ea327","vaultid":null,"uId":"05e2d8e0-b1fe-4f61-b74a-409010da0000","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>Many historical accounts of the 1930s focus on the widespread movement of people from dust bowl&ndash;ravaged Great Plains states to faraway California. However, a <span data-ssml-say-as=\"date\">2016</span> study of <span data-ssml-say-as=\"date\">1940</span> census data complicates this popular narrative; <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> researchers determined, migrants in states hardest hit by prolonged droughts and dust storms&mdash;Colorado, Kansas, Oklahoma, and Texas&mdash;merely relocated within the region.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"b808790a-dc64-4064-8ecb-ddd7ac0ea268","content":"<p>for this reason,</p>"},{"id":"7f906209-c0fc-46ac-8b9e-0203c94e6f4c","content":"<p>more often,</p>"},{"id":"b53a748c-a813-4bf1-ae7f-fe931674217d","content":"<p>additionally,</p>"},{"id":"ff620934-9a41-472e-9977-4c7b22c66b7d","content":"<p>nevertheless,</p>"}],"keys":["7f906209-c0fc-46ac-8b9e-0203c94e6f4c"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. &ldquo;More often&rdquo; logically signals that the historical outcome in this clause&mdash;dust bowl migrants&rsquo; relocation within the Great Plains region&mdash;was more common than the movement to California described in many historical accounts.</p><p>Choice A is incorrect because &ldquo;for this reason&rdquo; illogically signals that the historical outcome in this clause was caused by either the narrative about widespread movement to California or the 2016 study&rsquo;s complication of that narrative. Instead, dust bowl migrants&rsquo; regional relocation was found to be more common than the movement to California described in many historical accounts. Choice C is incorrect because &ldquo;additionally&rdquo; illogically signals that the historical outcome in this clause merely adds to either the narrative about widespread movement to California or the 2016 study&rsquo;s complication of that narrative. Instead, dust bowl migrants&rsquo; regional relocation was found to be more common than the movement to California described in many historical accounts. Choice D is incorrect because &ldquo;nevertheless&rdquo; illogically signals that the historical outcome in this clause is true despite either the narrative about widespread movement to California or the 2016 study&rsquo;s complication of that narrative. While the findings about dust bowl migrants&rsquo; regional relocation did challenge the previous narrative, they did not challenge the study&rsquo;s findings, and this choice creates a confusing ambiguity. Instead, dust bowl migrants&rsquo; regional relocation was found to be more common than the movement to California described in many historical accounts.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1776362771169,"updateDate":1776362771169}$SATQ$::jsonb, 1776362771169, 1776362771169),
    ($SATQ$d436a2b2$SATQ$, $SATQ$4c2dd37c-9e2d-4679-8905-90514624a673$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>Komodo dragons are the largest lizards in the world.</li>
<li>They live on four islands in Komodo National Park, Indonesia.</li>
<li>The park has a total of twenty-nine islands.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to emphasize how many islands in Komodo National Park have Komodo dragons living on them. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"478b0474-d1ec-4cf2-85e9-2869ff658cbc","content":"<p>Komodo dragons, the world&rsquo;s largest lizards, live on islands in Komodo National Park, Indonesia.</p>"},{"id":"ddece66c-2425-4360-a7ac-b9ad784b4780","content":"<p>The largest lizards in the world are found in Komodo National Park.</p>"},{"id":"b358a97f-8da8-43a8-9ce5-e4a2fe9ece15","content":"<p>Only four of the twenty-nine islands in Komodo National Park have Komodo dragons living on them.</p>"},{"id":"3e6ed705-6b49-4891-9266-bc5078d111b6","content":"<p>There are twenty-nine islands in Indonesia&rsquo;s Komodo National Park.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["b358a97f-8da8-43a8-9ce5-e4a2fe9ece15"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The sentence emphasizes the number of islands in Komodo National Park that have Komodo dragons living on them, noting that four of the park&rsquo;s twenty-nine islands have Komodo dragons.</p><p>Choice A is incorrect. While the sentence does explain that Komodo dragons live on the islands of Komodo National Park, it doesn&rsquo;t emphasize how many of those islands Komodo dragons live on. Choice B is incorrect. The sentence explains that Komodo National Park contains the world&rsquo;s largest lizards; it doesn&rsquo;t identify these lizards as Komodo dragons or emphasize how many of the park&rsquo;s islands the lizards live on. Choice D is incorrect. The sentence specifies the total number of islands in Komodo National Park; it doesn&rsquo;t emphasize how many of those islands have Komodo dragons.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"d436a2b2","external_id":"4c2dd37c-9e2d-4679-8905-90514624a673","vaultid":null,"uId":"4ffca885-8916-401e-bcdf-086fe99923c3","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>Komodo dragons are the largest lizards in the world.</li>\n<li>They live on four islands in Komodo National Park, Indonesia.</li>\n<li>The park has a total of twenty-nine islands.</li>\n</ul>","stem":"<p>The student wants to emphasize how many islands in Komodo National Park have Komodo dragons living on them. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"478b0474-d1ec-4cf2-85e9-2869ff658cbc","content":"<p>Komodo dragons, the world&rsquo;s largest lizards, live on islands in Komodo National Park, Indonesia.</p>"},{"id":"ddece66c-2425-4360-a7ac-b9ad784b4780","content":"<p>The largest lizards in the world are found in Komodo National Park.</p>"},{"id":"b358a97f-8da8-43a8-9ce5-e4a2fe9ece15","content":"<p>Only four of the twenty-nine islands in Komodo National Park have Komodo dragons living on them.</p>"},{"id":"3e6ed705-6b49-4891-9266-bc5078d111b6","content":"<p>There are twenty-nine islands in Indonesia&rsquo;s Komodo National Park.</p>"}],"keys":["b358a97f-8da8-43a8-9ce5-e4a2fe9ece15"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The sentence emphasizes the number of islands in Komodo National Park that have Komodo dragons living on them, noting that four of the park&rsquo;s twenty-nine islands have Komodo dragons.</p><p>Choice A is incorrect. While the sentence does explain that Komodo dragons live on the islands of Komodo National Park, it doesn&rsquo;t emphasize how many of those islands Komodo dragons live on. Choice B is incorrect. The sentence explains that Komodo National Park contains the world&rsquo;s largest lizards; it doesn&rsquo;t identify these lizards as Komodo dragons or emphasize how many of the park&rsquo;s islands the lizards live on. Choice D is incorrect. The sentence specifies the total number of islands in Komodo National Park; it doesn&rsquo;t emphasize how many of those islands have Komodo dragons.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323033,"updateDate":1730147323033}$SATQ$::jsonb, 1730147323033, 1730147323033),
    ($SATQ$d54e16ee$SATQ$, $SATQ$effb864f-3000-48f7-9ccc-b05ed09a2529$SATQ$::uuid, $SATQ$cedea86b-360d-4aea-9c3a-8d68d001d5fb$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>Originally coined by economist Joan Robinson to refer to markets with multiple sellers of a product but only one buyer, the term &ldquo;monopsony&rdquo; can also refer to markets where demand for labor is limited. In a product monopsony, the single buyer can force sellers to lower their prices. <span aria-hidden="true">______</span><span class="sr-only">blank</span> in a labor monopsony, employers can force workers to accept lower wages.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"412215af-358d-4029-b1f2-2ea83759e9b7","content":"<p>Earlier,</p>"},{"id":"22eea191-02fa-4ff3-b96e-39818ce51ac4","content":"<p>Instead,</p>"},{"id":"6f15907b-948d-46ec-9543-2d37022e1b00","content":"<p>Similarly,</p>"},{"id":"c99930c3-bdf0-4afc-93cb-0a2afab70781","content":"<p>In particular,</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["6f15907b-948d-46ec-9543-2d37022e1b00"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. &ldquo;Similarly&rdquo; logically signals that the information in this sentence about a labor monopsony is similar to the information in the previous sentence about a product monopsony. In both types of markets, one party (an employer or a buyer) has the power to force another party (a worker or seller) to accept less money (for labor or products). &nbsp;</p><p>Choice A is incorrect because &ldquo;earlier&rdquo; illogically signals that the information in this sentence about a labor monopsony occurs earlier (in a chronological sequence) than the information about a product monopsony. Instead, it is similar to the information about a product monopsony.&nbsp;Choice B is incorrect because &ldquo;instead&rdquo; illogically signals that the information in this sentence about a labor monopsony is an alternative to the previous information about a product monopsony. Instead, it is similar to the information about a product monopsony. &nbsp;Choice D is incorrect because &ldquo;in particular&rdquo; illogically signals that the information in this sentence about a labor monopsony provides specific details elaborating on the previous information about a product monopsony. Instead, it is similar to the information about a product monopsony. </p>$SATQ$, false, 0, $SATQ$OSP-274-TRA$SATQ$, $SATQ$$SATQ$, $SATQ$29cf0db0-d789-4b46-a714-b96c07e4feba$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"d54e16ee","external_id":"effb864f-3000-48f7-9ccc-b05ed09a2529","vaultid":"cedea86b-360d-4aea-9c3a-8d68d001d5fb","uId":"975841fe-6698-4b7d-8ecd-0f0602ebd11e","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>Originally coined by economist Joan Robinson to refer to markets with multiple sellers of a product but only one buyer, the term &ldquo;monopsony&rdquo; can also refer to markets where demand for labor is limited. In a product monopsony, the single buyer can force sellers to lower their prices. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> in a labor monopsony, employers can force workers to accept lower wages.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"412215af-358d-4029-b1f2-2ea83759e9b7","content":"<p>Earlier,</p>"},{"id":"22eea191-02fa-4ff3-b96e-39818ce51ac4","content":"<p>Instead,</p>"},{"id":"6f15907b-948d-46ec-9543-2d37022e1b00","content":"<p>Similarly,</p>"},{"id":"c99930c3-bdf0-4afc-93cb-0a2afab70781","content":"<p>In particular,</p>"}],"keys":["6f15907b-948d-46ec-9543-2d37022e1b00"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. &ldquo;Similarly&rdquo; logically signals that the information in this sentence about a labor monopsony is similar to the information in the previous sentence about a product monopsony. In both types of markets, one party (an employer or a buyer) has the power to force another party (a worker or seller) to accept less money (for labor or products). &nbsp;</p><p>Choice A is incorrect because &ldquo;earlier&rdquo; illogically signals that the information in this sentence about a labor monopsony occurs earlier (in a chronological sequence) than the information about a product monopsony. Instead, it is similar to the information about a product monopsony.&nbsp;Choice B is incorrect because &ldquo;instead&rdquo; illogically signals that the information in this sentence about a labor monopsony is an alternative to the previous information about a product monopsony. Instead, it is similar to the information about a product monopsony. &nbsp;Choice D is incorrect because &ldquo;in particular&rdquo; illogically signals that the information in this sentence about a labor monopsony provides specific details elaborating on the previous information about a product monopsony. Instead, it is similar to the information about a product monopsony. </p>","parenttemplatename":"OSP-274-TRA","parenttemplateid":"","templateclusterid":"29cf0db0-d789-4b46-a714-b96c07e4feba","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959334,"updateDate":1691007959334}$SATQ$::jsonb, 1691007959334, 1691007959334),
    ($SATQ$d6dec50e$SATQ$, $SATQ$9ea90b3d-ac35-409c-a561-ecb68172fc2b$SATQ$::uuid, $SATQ$319c0cb3-8aa1-4c68-88b0-486d19831e5f$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>In 2019, Emily Shepard and colleagues in the UK and Germany studied the effect of wind on auks&rsquo; success in landing at cliffside nesting sites.</li>
<li>They found as wind conditions intensified, the birds needed more attempts in order to make a successful landing.</li>
<li>When the wind was still, almost 100% of landing attempts were successful.</li>
<li>In a strong breeze, approximately 40% of attempts were successful.</li>
<li>In near-gale conditions, only around 20% of attempts were successful.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to summarize the study. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"b936f111-574e-4eeb-b222-8c563b2cd2dd","content":"<p>For a 2019 study, researchers from the UK and Germany collected data on auks&rsquo; attempts to land at cliffside nesting sites in different wind conditions.</p>"},{"id":"83dd8bfc-eb4e-4bfa-abed-17fa1366e445","content":"<p>Emily Shepard and her colleagues wanted to know the extent to which wind affected auks&rsquo; success in landing at cliffside nesting sites, so they conducted a study.</p>"},{"id":"4c091cda-eff9-45b9-a661-921aab01de2f","content":"<p>Knowing that auks often need multiple attempts to land at their cliffside nesting sites, Emily Shepard studied the birds&rsquo; success rate, which was only around 20% in some conditions.</p>"},{"id":"131c861b-16fd-4651-a62c-58f244d2ff1d","content":"<p>Emily Shepard&rsquo;s 2019 study of auks&rsquo; success in landing at cliffside nesting sites showed that as wind conditions intensified, the birds&rsquo; success rate decreased.</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["131c861b-16fd-4651-a62c-58f244d2ff1d"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The sentence effectively summarizes the study, noting who conducted it, when it was conducted, and what its results showed: that auks&rsquo; landing success rate decreased as wind conditions intensified. </p><p>Choice A is incorrect. While the sentence presents the methodology of the study&mdash;that is, the approach taken by the researchers&mdash;it fails to summarize the study as a whole. Choice B is incorrect. While the sentence presents the aim, or goal, of the study, it fails to summarize the study as a whole. Choice C is incorrect. While the sentence indicates what Shepard studied, it fails to mention a key factor: the effect of wind. It thus fails to summarize the study as a whole. </p>$SATQ$, false, 0, $SATQ$OSP-750-SYN$SATQ$, $SATQ$$SATQ$, $SATQ$88d66f26-87a2-4945-a657-020b07ab922f$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"d6dec50e","external_id":"9ea90b3d-ac35-409c-a561-ecb68172fc2b","vaultid":"319c0cb3-8aa1-4c68-88b0-486d19831e5f","uId":"58914316-6a2c-4a2d-aeeb-cf2034f916de","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>In 2019, Emily Shepard and colleagues in the UK and Germany studied the effect of wind on auks&rsquo; success in landing at cliffside nesting sites.</li>\n<li>They found as wind conditions intensified, the birds needed more attempts in order to make a successful landing.</li>\n<li>When the wind was still, almost 100% of landing attempts were successful.</li>\n<li>In a strong breeze, approximately 40% of attempts were successful.</li>\n<li>In near-gale conditions, only around 20% of attempts were successful.</li>\n</ul>","stem":"<p>The student wants to summarize the study. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"b936f111-574e-4eeb-b222-8c563b2cd2dd","content":"<p>For a 2019 study, researchers from the UK and Germany collected data on auks&rsquo; attempts to land at cliffside nesting sites in different wind conditions.</p>"},{"id":"83dd8bfc-eb4e-4bfa-abed-17fa1366e445","content":"<p>Emily Shepard and her colleagues wanted to know the extent to which wind affected auks&rsquo; success in landing at cliffside nesting sites, so they conducted a study.</p>"},{"id":"4c091cda-eff9-45b9-a661-921aab01de2f","content":"<p>Knowing that auks often need multiple attempts to land at their cliffside nesting sites, Emily Shepard studied the birds&rsquo; success rate, which was only around 20% in some conditions.</p>"},{"id":"131c861b-16fd-4651-a62c-58f244d2ff1d","content":"<p>Emily Shepard&rsquo;s 2019 study of auks&rsquo; success in landing at cliffside nesting sites showed that as wind conditions intensified, the birds&rsquo; success rate decreased.</p>"}],"keys":["131c861b-16fd-4651-a62c-58f244d2ff1d"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The sentence effectively summarizes the study, noting who conducted it, when it was conducted, and what its results showed: that auks&rsquo; landing success rate decreased as wind conditions intensified. </p><p>Choice A is incorrect. While the sentence presents the methodology of the study&mdash;that is, the approach taken by the researchers&mdash;it fails to summarize the study as a whole. Choice B is incorrect. While the sentence presents the aim, or goal, of the study, it fails to summarize the study as a whole. Choice C is incorrect. While the sentence indicates what Shepard studied, it fails to mention a key factor: the effect of wind. It thus fails to summarize the study as a whole. </p>","parenttemplatename":"OSP-750-SYN","parenttemplateid":"","templateclusterid":"88d66f26-87a2-4945-a657-020b07ab922f","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959350,"updateDate":1691007959350}$SATQ$::jsonb, 1691007959350, 1691007959350),
    ($SATQ$d7c5388f$SATQ$, $SATQ$da67f89e-3c3e-4f3a-b7d2-21819515497c$SATQ$::uuid, $SATQ$b224f44f-964e-4b60-a13c-63f2adad5d7b$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>Planetary scientists classify asteroids based on their composition.</li>
<li>C-type asteroids are composed primarily of carbon.</li>
<li>They account for roughly 75 percent of known asteroids.</li>
<li>S-type asteroids are primarily made up of silicate minerals.</li>
<li>They account for roughly 17 percent of known asteroids.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to emphasize a difference between C-type and S-type asteroids. Which choice most effectively uses relevant information from the notes to accomplish this goal?&nbsp;</p>$SATQ$, $SATQ$[{"id":"c98a3ecb-0754-4f25-88fb-e3f3082a8eef","content":"<p>Planetary scientists classify asteroids into types, two of which are the C-type and the S-type.</p>"},{"id":"56016490-37c8-4895-b8fa-75b955939253","content":"<p>Planetary scientists consider an asteroid&rsquo;s composition (such as whether the asteroid is composed mainly of silicate minerals or carbon) when classifying it.</p>"},{"id":"51dc8e50-3698-43bd-9781-9ea32a4a2cda","content":"<p>Roughly 17 percent of known asteroids are classified as S-type asteroids; another percentage is classified as C-type asteroids.&nbsp;</p>"},{"id":"35c11780-3e80-4958-b17d-3006233c22eb","content":"<p>C-type asteroids are mainly composed of carbon, whereas S-type asteroids are primarily made up of silicate minerals.</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["35c11780-3e80-4958-b17d-3006233c22eb"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The sentence emphasizes a difference between C-type and S-type asteroids, noting that C-type asteroids are mainly composed of carbon, while S-type asteroids are mainly composed of silicate minerals. </p><p>Choice A is incorrect. The sentence states that C-type and S-type are two types of asteroids, but it doesn&rsquo;t emphasize a difference between them. Choice B is incorrect because it doesn&rsquo;t directly mention C-type or S-type asteroids.&nbsp;Choice C is incorrect. While the sentence mentions that 17 percent of known asteroids are S-type asteroids, it doesn&rsquo;t identify the percentage of asteroids that are C-type. Therefore, the sentence doesn&rsquo;t emphasize a difference between the two types. </p>$SATQ$, false, 0, $SATQ$OSP-763-SYN$SATQ$, $SATQ$$SATQ$, $SATQ$496796b3-4b48-4c8a-b0f9-3e917dfe8be5$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"d7c5388f","external_id":"da67f89e-3c3e-4f3a-b7d2-21819515497c","vaultid":"b224f44f-964e-4b60-a13c-63f2adad5d7b","uId":"9bd07567-f642-4371-ba6a-e3dc78d08874","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>Planetary scientists classify asteroids based on their composition.</li>\n<li>C-type asteroids are composed primarily of carbon.</li>\n<li>They account for roughly 75 percent of known asteroids.</li>\n<li>S-type asteroids are primarily made up of silicate minerals.</li>\n<li>They account for roughly 17 percent of known asteroids.</li>\n</ul>","stem":"<p>The student wants to emphasize a difference between C-type and S-type asteroids. Which choice most effectively uses relevant information from the notes to accomplish this goal?&nbsp;</p>","answerOptions":[{"id":"c98a3ecb-0754-4f25-88fb-e3f3082a8eef","content":"<p>Planetary scientists classify asteroids into types, two of which are the C-type and the S-type.</p>"},{"id":"56016490-37c8-4895-b8fa-75b955939253","content":"<p>Planetary scientists consider an asteroid&rsquo;s composition (such as whether the asteroid is composed mainly of silicate minerals or carbon) when classifying it.</p>"},{"id":"51dc8e50-3698-43bd-9781-9ea32a4a2cda","content":"<p>Roughly 17 percent of known asteroids are classified as S-type asteroids; another percentage is classified as C-type asteroids.&nbsp;</p>"},{"id":"35c11780-3e80-4958-b17d-3006233c22eb","content":"<p>C-type asteroids are mainly composed of carbon, whereas S-type asteroids are primarily made up of silicate minerals.</p>"}],"keys":["35c11780-3e80-4958-b17d-3006233c22eb"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The sentence emphasizes a difference between C-type and S-type asteroids, noting that C-type asteroids are mainly composed of carbon, while S-type asteroids are mainly composed of silicate minerals. </p><p>Choice A is incorrect. The sentence states that C-type and S-type are two types of asteroids, but it doesn&rsquo;t emphasize a difference between them. Choice B is incorrect because it doesn&rsquo;t directly mention C-type or S-type asteroids.&nbsp;Choice C is incorrect. While the sentence mentions that 17 percent of known asteroids are S-type asteroids, it doesn&rsquo;t identify the percentage of asteroids that are C-type. Therefore, the sentence doesn&rsquo;t emphasize a difference between the two types. </p>","parenttemplatename":"OSP-763-SYN","parenttemplateid":"","templateclusterid":"496796b3-4b48-4c8a-b0f9-3e917dfe8be5","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959351,"updateDate":1691007959351}$SATQ$::jsonb, 1691007959351, 1691007959351),
    ($SATQ$d7f31e68$SATQ$, $SATQ$b55400a0-38cf-4584-94ad-7d3b5cf2d570$SATQ$::uuid, $SATQ$c77cc51c-4466-405f-80cb-a80dd2fd8a25$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:&nbsp;</p>
<ul>
<li>Annie Wu is a prominent American flutist who graduated from the New England Conservatory.</li>
<li>She has won multiple national flute competitions.</li>
<li>She is best known for a 2011 YouTube video that has been viewed over two million times.</li>
<li>The video shows her performing <em>Three Beats for Beatbox Flute, </em>an original work by composer Greg Pattillo.</li>
<li>Wu combines flute playing and beatboxing in the video.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to emphasize Wu&rsquo;s most well-known achievement. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"8f454e8f-4d54-49e2-a3ff-6d5b68e68c2b","content":"<p>Annie Wu, who has won multiple national flute competitions, has also combined flute playing and beatboxing.</p>"},{"id":"2c5318ac-4704-4187-b202-94929354468a","content":"<p>Among her many achievements, prominent American flutist Annie Wu graduated from the New England Conservatory and has won multiple national flute competitions.</p>"},{"id":"6165b530-7231-4fde-92f7-2edd6a12e4bb","content":"<p>Annie Wu is best known for a 2011 YouTube video performance of <em>Three Beats for Beatbox Flute </em>that has been viewed over two million times.</p>"},{"id":"9e67011f-060e-4c23-99d1-29ef3e5c912c","content":"<p>Composer Greg Pattillo&rsquo;s original work <em>Three Beats for Beatbox Flute</em> combines flute playing and beatboxing.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["6165b530-7231-4fde-92f7-2edd6a12e4bb"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. This describes the achievement for which Wu is best known. </p><p>Choice A is incorrect. This choice doesn&rsquo;t emphasize Wu&rsquo;s most well-known achievement. It mentions some of her general achievements, but not the one for which she is &ldquo;best known.&rdquo; Choice B is incorrect. This choice doesn&rsquo;t emphasize Wu&rsquo;s most well-known achievement&mdash;it describes several of her achievements equally. Choice D is incorrect. This choice doesn&rsquo;t emphasize Wu&rsquo;s most well-known achievement. It describes a piece of music featured in her most well-known achievement. </p>$SATQ$, false, 0, $SATQ$OSP-KA-SYN-E004$SATQ$, $SATQ$$SATQ$, $SATQ$796b0dd3-d548-430d-8001-ba63fe15324f$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"d7f31e68","external_id":"b55400a0-38cf-4584-94ad-7d3b5cf2d570","vaultid":"c77cc51c-4466-405f-80cb-a80dd2fd8a25","uId":"e3bcdd26-b017-412c-af48-011627b03067","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:&nbsp;</p>\n<ul>\n<li>Annie Wu is a prominent American flutist who graduated from the New England Conservatory.</li>\n<li>She has won multiple national flute competitions.</li>\n<li>She is best known for a 2011 YouTube video that has been viewed over two million times.</li>\n<li>The video shows her performing <em>Three Beats for Beatbox Flute, </em>an original work by composer Greg Pattillo.</li>\n<li>Wu combines flute playing and beatboxing in the video.</li>\n</ul>","stem":"<p>The student wants to emphasize Wu&rsquo;s most well-known achievement. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"8f454e8f-4d54-49e2-a3ff-6d5b68e68c2b","content":"<p>Annie Wu, who has won multiple national flute competitions, has also combined flute playing and beatboxing.</p>"},{"id":"2c5318ac-4704-4187-b202-94929354468a","content":"<p>Among her many achievements, prominent American flutist Annie Wu graduated from the New England Conservatory and has won multiple national flute competitions.</p>"},{"id":"6165b530-7231-4fde-92f7-2edd6a12e4bb","content":"<p>Annie Wu is best known for a 2011 YouTube video performance of <em>Three Beats for Beatbox Flute </em>that has been viewed over two million times.</p>"},{"id":"9e67011f-060e-4c23-99d1-29ef3e5c912c","content":"<p>Composer Greg Pattillo&rsquo;s original work <em>Three Beats for Beatbox Flute</em> combines flute playing and beatboxing.</p>"}],"keys":["6165b530-7231-4fde-92f7-2edd6a12e4bb"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. This describes the achievement for which Wu is best known. </p><p>Choice A is incorrect. This choice doesn&rsquo;t emphasize Wu&rsquo;s most well-known achievement. It mentions some of her general achievements, but not the one for which she is &ldquo;best known.&rdquo; Choice B is incorrect. This choice doesn&rsquo;t emphasize Wu&rsquo;s most well-known achievement&mdash;it describes several of her achievements equally. Choice D is incorrect. This choice doesn&rsquo;t emphasize Wu&rsquo;s most well-known achievement. It describes a piece of music featured in her most well-known achievement. </p>","parenttemplatename":"OSP-KA-SYN-E004","parenttemplateid":"","templateclusterid":"796b0dd3-d548-430d-8001-ba63fe15324f","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959371,"updateDate":1691007959371}$SATQ$::jsonb, 1691007959371, 1691007959371),
    ($SATQ$d8aa8ba2$SATQ$, $SATQ$bdd1b170-ff13-4936-a7ea-0f1ff0845133$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>In astronomy, the mass of stars can be described in units called solar masses.</li>
<li>One solar mass is roughly equal to the mass of the Sun.</li>
<li>The mass of the star Proxima Centauri is 0.122 solar masses.</li>
<li>The mass of the star Sirius A is 2.063 solar masses.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to emphasize the mass of Sirius A. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"3a93d380-6073-48ee-9b0f-93c1c9ed8e62","content":"<p>The mass of stars, like Proxima Centauri, can be described in units called solar masses.</p>"},{"id":"bff92326-cc4c-4e9a-857f-b1155e56c448","content":"<p>In astronomy, the mass of stars can be described in units called solar masses, and one solar mass is roughly equal to the mass of the Sun.</p>"},{"id":"81c082fc-c7b0-4588-8782-cc72989a606a","content":"<p>The Sun is more massive than Proxima Centauri, which has a mass of 0.122 solar masses.</p>"},{"id":"ad2eb535-a000-4c4e-9b42-0ac67ac3c5aa","content":"<p>With a mass of 2.063 solar masses, Sirius A is more massive than the Sun.</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["ad2eb535-a000-4c4e-9b42-0ac67ac3c5aa"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The sentence emphasizes the mass of Sirius A, noting that it has a mass of 2.063 solar masses and that it is larger than the Sun.</p><p>Choice A is incorrect. The sentence makes a generalization about how the mass of stars can be measured; it doesn&rsquo;t emphasize the mass of Sirius A. Choice B is incorrect. The sentence introduces solar masses as a unit of measurement; it doesn&rsquo;t emphasize the mass of Sirius A. Choice C is incorrect. The sentence emphasizes the mass of Proxima Centauri, not the mass of Sirius A.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"d8aa8ba2","external_id":"bdd1b170-ff13-4936-a7ea-0f1ff0845133","vaultid":null,"uId":"69dd585e-e810-47f6-8c09-b2aecef2eb01","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>In astronomy, the mass of stars can be described in units called solar masses.</li>\n<li>One solar mass is roughly equal to the mass of the Sun.</li>\n<li>The mass of the star Proxima Centauri is 0.122 solar masses.</li>\n<li>The mass of the star Sirius A is 2.063 solar masses.</li>\n</ul>","stem":"<p>The student wants to emphasize the mass of Sirius A. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"3a93d380-6073-48ee-9b0f-93c1c9ed8e62","content":"<p>The mass of stars, like Proxima Centauri, can be described in units called solar masses.</p>"},{"id":"bff92326-cc4c-4e9a-857f-b1155e56c448","content":"<p>In astronomy, the mass of stars can be described in units called solar masses, and one solar mass is roughly equal to the mass of the Sun.</p>"},{"id":"81c082fc-c7b0-4588-8782-cc72989a606a","content":"<p>The Sun is more massive than Proxima Centauri, which has a mass of 0.122 solar masses.</p>"},{"id":"ad2eb535-a000-4c4e-9b42-0ac67ac3c5aa","content":"<p>With a mass of 2.063 solar masses, Sirius A is more massive than the Sun.</p>"}],"keys":["ad2eb535-a000-4c4e-9b42-0ac67ac3c5aa"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The sentence emphasizes the mass of Sirius A, noting that it has a mass of 2.063 solar masses and that it is larger than the Sun.</p><p>Choice A is incorrect. The sentence makes a generalization about how the mass of stars can be measured; it doesn&rsquo;t emphasize the mass of Sirius A. Choice B is incorrect. The sentence introduces solar masses as a unit of measurement; it doesn&rsquo;t emphasize the mass of Sirius A. Choice C is incorrect. The sentence emphasizes the mass of Proxima Centauri, not the mass of Sirius A.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323032,"updateDate":1730147323032}$SATQ$::jsonb, 1730147323032, 1730147323032),
    ($SATQ$d9d314d9$SATQ$, $SATQ$d6d5fa78-74b9-4d37-a15f-af9162d592aa$SATQ$::uuid, $SATQ$3ad01216-8856-4bf4-b97b-b8871ae2c466$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>Pinnipeds, which include seals, sea lions, and walruses, live in and around water.</li>
<li>Pinnipeds are descended not from sea animals but from four-legged, land-dwelling carnivores.</li>
<li>Canadian paleobiologist Natalia Rybczynski recently found a fossil with four legs, webbed toes, and the skull and teeth of a seal.</li>
<li>Rybczynski refers to her rare find as a &ldquo;transitional fossil.&rdquo;</li>
<li>The fossil illustrates an early stage in the evolution of pinnipeds from their land-dwelling ancestors.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to emphasize the fossil&rsquo;s significance. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"6db33667-e3ce-4e53-acbe-b6bb1cf6bc29","content":"<p>Canadian paleobiologist Natalia Rybczynski&rsquo;s fossil has the skull and teeth of a seal, which, like sea lions and walruses, is a pinniped.</p>"},{"id":"47ba6000-171a-42ec-a5e6-8df4031c2655","content":"<p>Pinnipeds are descended from four-legged, land-dwelling carnivores; a fossil that resembles both was recently found.</p>"},{"id":"f2eb9c72-ba5b-4879-a71a-1b6ba69143fd","content":"<p>Having four legs but the skull and teeth of a seal, the rare fossil illustrates an early stage in the evolution of pinnipeds from their land-dwelling ancestors.</p>"},{"id":"5d8f27cb-0ad7-48d2-8fc4-87d53c51bfdd","content":"<p>A &ldquo;transitional fossil&rdquo; was recently found by paleobiologist Natalia Rybczynski.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["f2eb9c72-ba5b-4879-a71a-1b6ba69143fd"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The sentence effectively emphasizes the fossil&rsquo;s significance, explaining that the fossil is rare and illustrates an early stage in the evolution of pinnipeds from their land-dwelling ancestors. </p><p>Choice A is incorrect. The sentence describes the fossil Rybczynski found; it doesn&rsquo;t emphasize the fossil&rsquo;s significance. Choice B is incorrect. The sentence mentions that a fossil resembling both pinnipeds and their ancestors was found; it doesn&rsquo;t emphasize the fossil&rsquo;s significance.&nbsp;Choice D is incorrect. The sentence notes a term used to describe the fossil Rybczynski found; it doesn&rsquo;t emphasize the fossil&rsquo;s significance.&nbsp;</p>$SATQ$, false, 0, $SATQ$OSP-785-SYN$SATQ$, $SATQ$$SATQ$, $SATQ$a9b9d0ee-efc2-4bc6-a850-bdca409e008b$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"d9d314d9","external_id":"d6d5fa78-74b9-4d37-a15f-af9162d592aa","vaultid":"3ad01216-8856-4bf4-b97b-b8871ae2c466","uId":"ad3b357a-3a12-400a-b307-b002a82073cd","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>Pinnipeds, which include seals, sea lions, and walruses, live in and around water.</li>\n<li>Pinnipeds are descended not from sea animals but from four-legged, land-dwelling carnivores.</li>\n<li>Canadian paleobiologist Natalia Rybczynski recently found a fossil with four legs, webbed toes, and the skull and teeth of a seal.</li>\n<li>Rybczynski refers to her rare find as a &ldquo;transitional fossil.&rdquo;</li>\n<li>The fossil illustrates an early stage in the evolution of pinnipeds from their land-dwelling ancestors.</li>\n</ul>","stem":"<p>The student wants to emphasize the fossil&rsquo;s significance. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"6db33667-e3ce-4e53-acbe-b6bb1cf6bc29","content":"<p>Canadian paleobiologist Natalia Rybczynski&rsquo;s fossil has the skull and teeth of a seal, which, like sea lions and walruses, is a pinniped.</p>"},{"id":"47ba6000-171a-42ec-a5e6-8df4031c2655","content":"<p>Pinnipeds are descended from four-legged, land-dwelling carnivores; a fossil that resembles both was recently found.</p>"},{"id":"f2eb9c72-ba5b-4879-a71a-1b6ba69143fd","content":"<p>Having four legs but the skull and teeth of a seal, the rare fossil illustrates an early stage in the evolution of pinnipeds from their land-dwelling ancestors.</p>"},{"id":"5d8f27cb-0ad7-48d2-8fc4-87d53c51bfdd","content":"<p>A &ldquo;transitional fossil&rdquo; was recently found by paleobiologist Natalia Rybczynski.</p>"}],"keys":["f2eb9c72-ba5b-4879-a71a-1b6ba69143fd"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The sentence effectively emphasizes the fossil&rsquo;s significance, explaining that the fossil is rare and illustrates an early stage in the evolution of pinnipeds from their land-dwelling ancestors. </p><p>Choice A is incorrect. The sentence describes the fossil Rybczynski found; it doesn&rsquo;t emphasize the fossil&rsquo;s significance. Choice B is incorrect. The sentence mentions that a fossil resembling both pinnipeds and their ancestors was found; it doesn&rsquo;t emphasize the fossil&rsquo;s significance.&nbsp;Choice D is incorrect. The sentence notes a term used to describe the fossil Rybczynski found; it doesn&rsquo;t emphasize the fossil&rsquo;s significance.&nbsp;</p>","parenttemplatename":"OSP-785-SYN","parenttemplateid":"","templateclusterid":"a9b9d0ee-efc2-4bc6-a850-bdca409e008b","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959353,"updateDate":1691007959353}$SATQ$::jsonb, 1691007959353, 1691007959353),
    ($SATQ$d9dad012$SATQ$, $SATQ$a0d52b5d-8503-42b3-a30f-685beeea0d92$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>The Inca of South America used intricately knotted string devices called quipus to record countable information, like population data and payments. <span aria-hidden="true">______</span><span class="sr-only">blank</span> they may have used quipus to record more complex information, like stories and myths, according to researchers.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"3a587f0c-a576-4aa2-b6f8-849f39523b86","content":"<p>As a result,</p>"},{"id":"f56c7ee8-8691-4388-9b94-e49280b1050f","content":"<p>In other words,</p>"},{"id":"5c43f81e-be8a-4e9d-afd5-739702da62f7","content":"<p>In addition,</p>"},{"id":"78564186-bae1-429a-a71c-c23beda8355f","content":"<p>For example,</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["5c43f81e-be8a-4e9d-afd5-739702da62f7"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. "In addition" logically signals that the claim in this sentence&mdash;that the Inca of South America may have used quipus to record more complex information&mdash;is an additional point related to the previous statement about the Inca using quipus to record countable information.</p><p>Choice A is incorrect because "as a result" illogically signals that the claim in the sentence is a consequence or result of the previous statement about the Inca using quipus to record countable information. Instead, the possibility that the Inca used quipus to record more complex information is an additional point about how the quipus were used. Choice B is incorrect because "in other words" illogically signals that the claim in the sentence is merely a paraphrase or restatement of the previous statement about the Inca using quipus to record countable information. Instead, the possibility that the Inca used quipus to record more complex information is an additional point about how the quipus were used. Choice D is incorrect because "for example" illogically signals that the claim in the sentence exemplifies the previous statement about the Inca using quipus to record countable information. Instead, the possibility that the Inca used quipus to record more complex information is an additional point about how the quipus were used.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"d9dad012","external_id":"a0d52b5d-8503-42b3-a30f-685beeea0d92","vaultid":null,"uId":"0ebd8e3f-f6f1-4094-814c-999c2b32a92a","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>The Inca of South America used intricately knotted string devices called quipus to record countable information, like population data and payments. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> they may have used quipus to record more complex information, like stories and myths, according to researchers.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"3a587f0c-a576-4aa2-b6f8-849f39523b86","content":"<p>As a result,</p>"},{"id":"f56c7ee8-8691-4388-9b94-e49280b1050f","content":"<p>In other words,</p>"},{"id":"5c43f81e-be8a-4e9d-afd5-739702da62f7","content":"<p>In addition,</p>"},{"id":"78564186-bae1-429a-a71c-c23beda8355f","content":"<p>For example,</p>"}],"keys":["5c43f81e-be8a-4e9d-afd5-739702da62f7"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. \"In addition\" logically signals that the claim in this sentence&mdash;that the Inca of South America may have used quipus to record more complex information&mdash;is an additional point related to the previous statement about the Inca using quipus to record countable information.</p><p>Choice A is incorrect because \"as a result\" illogically signals that the claim in the sentence is a consequence or result of the previous statement about the Inca using quipus to record countable information. Instead, the possibility that the Inca used quipus to record more complex information is an additional point about how the quipus were used. Choice B is incorrect because \"in other words\" illogically signals that the claim in the sentence is merely a paraphrase or restatement of the previous statement about the Inca using quipus to record countable information. Instead, the possibility that the Inca used quipus to record more complex information is an additional point about how the quipus were used. Choice D is incorrect because \"for example\" illogically signals that the claim in the sentence exemplifies the previous statement about the Inca using quipus to record countable information. Instead, the possibility that the Inca used quipus to record more complex information is an additional point about how the quipus were used.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323043,"updateDate":1730147323043}$SATQ$::jsonb, 1730147323043, 1730147323043)
